package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * A tick is lost when the next attack is late. Deciding that needs two clocks
 * kept straight: the attack goes out on one tick and is booked a tick or two
 * later, and how much later depends on what proves it — a hitsplat for melee,
 * a projectile for the rest.
 *
 * <p>Every case here is one attack thrown on tick 0 with a four tick weapon, so
 * the next is due on tick 4. What changes is the lag of the attack being waited
 * for, which is the lag of the weapon in hand and not of the one that threw.
 */
public class AttackDueTest
{
	private static final int MELEE = 1;
	private static final int PROJECTILE = 2;
	private static final int DUE = 4;

	@Test
	public void meleeIntoMeleeIsNeverLateWhileOnTime()
	{
		// The blow lands on the tick it is thrown, so the booking for an attack
		// thrown on 4 arrives on 5. Nothing before that is late.
		assertFalse(PvmPerformancePlugin.attackOverdue(3, DUE, MELEE));
		assertFalse(PvmPerformancePlugin.attackOverdue(4, DUE, MELEE));
		assertTrue(PvmPerformancePlugin.attackOverdue(5, DUE, MELEE));
	}

	@Test
	public void projectileIntoProjectileIsNeverLateWhileOnTime()
	{
		// A projectile surfaces two ticks after it is fired, so the booking for
		// an attack thrown on 4 arrives on 6.
		assertFalse(PvmPerformancePlugin.attackOverdue(5, DUE, PROJECTILE));
		assertTrue(PvmPerformancePlugin.attackOverdue(6, DUE, PROJECTILE));
	}

	/**
	 * The case that was wrong. A whip attack followed by a switch to a trident:
	 * the trident goes out on time, on tick 4, but is not booked until tick 6.
	 * Measured against the whip's one tick lag, tick 5 looked like a tick with
	 * nothing happening in it, and every switch into a projectile weapon booked
	 * a lost tick that never happened.
	 */
	@Test
	public void switchingIntoAProjectileWeaponCostsNothing()
	{
		assertFalse(PvmPerformancePlugin.attackOverdue(5, DUE, PROJECTILE));
	}

	/**
	 * And the other way, which hid the bug: switching into melee shortens the
	 * wait, so the booking arrives before anything could be called late.
	 */
	@Test
	public void switchingIntoMeleeArrivesEarlyRatherThanLate()
	{
		// The lag here is the projectile one, because the attack being waited
		// for was thrown before the switch.
		assertFalse(PvmPerformancePlugin.attackOverdue(4, DUE, PROJECTILE));
	}

	@Test
	public void aRealPauseIsStillLate()
	{
		// The forgiveness is one tick of booking lag, not a free tick. Idle past
		// it and both styles report it.
		assertTrue(PvmPerformancePlugin.attackOverdue(9, DUE, MELEE));
		assertTrue(PvmPerformancePlugin.attackOverdue(9, DUE, PROJECTILE));
	}

	/**
	 * Taken straight from a trace. A dart went out on 162 and another on 164,
	 * both on time for a two tick weapon, and the whip came out on 165. Tick
	 * 165 was booked lost because the lag was read off the whip, while the
	 * booking being waited for belonged to the dart already in the air — it
	 * arrived on 166 exactly as a projectile should.
	 */
	@Test
	public void aDartStillInFlightKeepsItsOwnLag()
	{
		final int dueAfterTheDartOn162 = 164;
		final int lag = PvmPerformancePlugin.pendingBookingLag(true, true);
		assertEquals(PROJECTILE, lag);
		assertFalse(PvmPerformancePlugin.attackOverdue(165, dueAfterTheDartOn162, lag));
		// And the dart's booking lands on 166, so nothing was ever late.
	}

	@Test
	public void theLongerOfTheTwoLagsWins()
	{
		// Melee thrown, projectile weapon now in hand: the next attack is the
		// slow one to surface.
		assertEquals(PROJECTILE, PvmPerformancePlugin.pendingBookingLag(false, false));
		// Projectile thrown, melee now in hand: the one already in the air is.
		assertEquals(PROJECTILE, PvmPerformancePlugin.pendingBookingLag(true, true));
		// Melee either side is the only case that can be judged a tick sooner.
		assertEquals(MELEE, PvmPerformancePlugin.pendingBookingLag(false, true));
		assertEquals(PROJECTILE, PvmPerformancePlugin.pendingBookingLag(true, false));
	}

	@Test
	public void theLongerLagStillEndsInALostTick()
	{
		// Leniency that never expires would be a hole. Two ticks past the
		// deadline nothing can still be in flight, and the tick is lost.
		assertTrue(PvmPerformancePlugin.attackOverdue(6, DUE, PROJECTILE));
	}

	@Test
	public void nothingIsDueBeforeTheFirstAttack()
	{
		// No attack yet leaves the due tick at its floor, which must read as
		// overdue rather than wrapping into the far future.
		assertTrue(PvmPerformancePlugin.attackOverdue(0, Integer.MIN_VALUE, PROJECTILE));
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;

/**
 * The stand-in ids, which are transcription and nothing else. Each one says
 * "the wiki data has no entry for the form this monster is FOUGHT in, so read
 * the form it is listed under instead", and getting one wrong is silent: the
 * figures still appear, they are just another monster's.
 *
 * <p>Every mapping here was checked against the entry it points at before it was
 * written down. What the tests can still catch is a later edit pointing one
 * somewhere else, or an alias that quietly points at another alias.
 */
public class MonsterStatsAliasTest
{
	private static final int[] ALIASED =
	{
		NpcID.OLM_HAND_RIGHT, NpcID.OLM_HAND_RIGHT_DYING, NpcID.OLM_HAND_LEFT, NpcID.OLM_HAND_LEFT_DYING,
		NpcID.OLM_HEAD, NpcID.RAIDS_STONEGUARDIANS_RIGHT, NpcID.RAIDS_STONEGUARDIANS_LEFT_DEAD,
		NpcID.RAIDS_STONEGUARDIANS_RIGHT_DEAD, NpcID.VERZIK_PHASE1, NpcID.VERZIK_PHASE1_HARD,
		NpcID.VERZIK_PHASE1_STORY, NpcID.TOB_XARPUS_STATIC, NpcID.TOB_XARPUS_FEEDING,
		NpcID.TOB_XARPUS_STATIC_HARD, NpcID.TOB_XARPUS_FEEDING_HARD, NpcID.TOB_XARPUS_STATIC_STORY,
		NpcID.TOB_XARPUS_FEEDING_STORY, NpcID.RAIDS_TEKTON_WALKING_STANDARD, NpcID.RAIDS_TEKTON_FIGHTING_STANDARD,
		NpcID.RAIDS_TEKTON_FIGHTING_ENRAGED, NpcID.TOA_WARDEN_ELIDINIS_PHASE2_RANGE,
		NpcID.TOA_WARDEN_TUMEKEN_PHASE2_RANGE, NpcID.TOB_NYLOCAS_FIGHTING_MELEE, NpcID.TOB_NYLOCAS_FIGHTING_RANGED,
		NpcID.TOB_NYLOCAS_FIGHTING_MAGIC, NpcID.TOB_NYLOCAS_BIG_FIGHTING_MELEE,
		NpcID.TOB_NYLOCAS_BIG_FIGHTING_RANGED, NpcID.TOB_NYLOCAS_BIG_FIGHTING_MAGIC,
		NpcID.TOB_MAIDEN_70_HARD, NpcID.TOB_MAIDEN_30_STORY,
	};

	@Test
	public void theOlmIsReadFromTheFormHeRisesIn()
	{
		// The three parts disagree on every defence they have, so each points at its OWN entry and never at a sibling.
		assertEquals(NpcID.OLM_HAND_LEFT_SPAWNING, MonsterStatsProvider.aliasFor(NpcID.OLM_HAND_LEFT));
		assertEquals(NpcID.OLM_HAND_RIGHT_SPAWNING, MonsterStatsProvider.aliasFor(NpcID.OLM_HAND_RIGHT));
		assertEquals(NpcID.OLM_HEAD_SPAWNING, MonsterStatsProvider.aliasFor(NpcID.OLM_HEAD));
		assertNotEquals(MonsterStatsProvider.aliasFor(NpcID.OLM_HAND_LEFT),
			MonsterStatsProvider.aliasFor(NpcID.OLM_HAND_RIGHT));
	}

	@Test
	public void verziksFirstPhaseIsNotHerThrone()
	{
		// The data's "Phase 1" is the id she sits in before the fight; the fought form is the next one along. Her phases
		// differ by an order of magnitude in defence, so this is the mapping least survivable if it drifts.
		assertEquals(NpcID.VERZIK_INITIAL, MonsterStatsProvider.aliasFor(NpcID.VERZIK_PHASE1));
		assertEquals(NpcID.VERZIK_INITIAL_HARD, MonsterStatsProvider.aliasFor(NpcID.VERZIK_PHASE1_HARD));
		assertEquals(NpcID.VERZIK_INITIAL_STORY, MonsterStatsProvider.aliasFor(NpcID.VERZIK_PHASE1_STORY));
	}

	@Test
	public void tektonKeepsHisEnragedBonusesApartFromHisStandardOnes()
	{
		assertEquals(NpcID.RAIDS_TEKTON_WAITING, MonsterStatsProvider.aliasFor(NpcID.RAIDS_TEKTON_FIGHTING_STANDARD));
		assertEquals(NpcID.RAIDS_TEKTON_WALKING_ENRAGED,
			MonsterStatsProvider.aliasFor(NpcID.RAIDS_TEKTON_FIGHTING_ENRAGED));
		assertNotEquals(MonsterStatsProvider.aliasFor(NpcID.RAIDS_TEKTON_FIGHTING_STANDARD),
			MonsterStatsProvider.aliasFor(NpcID.RAIDS_TEKTON_FIGHTING_ENRAGED));
	}

	@Test
	public void aNylocasKeepsItsColourAndItsSize()
	{
		// Colour decides which defences apply and size decides how many times a scythe hits, so a settled nylocas must
		// point at its own colour AND its own size, never at the other one.
		assertEquals(NpcID.TOB_NYLOCAS_INCOMING_MELEE, MonsterStatsProvider.aliasFor(NpcID.TOB_NYLOCAS_FIGHTING_MELEE));
		assertEquals(NpcID.TOB_NYLOCAS_BIG_INCOMING_MELEE,
			MonsterStatsProvider.aliasFor(NpcID.TOB_NYLOCAS_BIG_FIGHTING_MELEE));
		assertEquals(NpcID.TOB_NYLOCAS_INCOMING_MAGIC, MonsterStatsProvider.aliasFor(NpcID.TOB_NYLOCAS_FIGHTING_MAGIC));
		assertNotEquals(MonsterStatsProvider.aliasFor(NpcID.TOB_NYLOCAS_FIGHTING_MELEE),
			MonsterStatsProvider.aliasFor(NpcID.TOB_NYLOCAS_BIG_FIGHTING_MELEE));
	}

	@Test
	public void bothGuardiansReadFromTheOneThatIsListed()
	{
		assertEquals(NpcID.RAIDS_STONEGUARDIANS_LEFT,
			MonsterStatsProvider.aliasFor(NpcID.RAIDS_STONEGUARDIANS_RIGHT));
		// The one that IS listed must not be aliased: it would send the lookup somewhere it never needed to go.
		assertEquals(-1, MonsterStatsProvider.aliasFor(NpcID.RAIDS_STONEGUARDIANS_LEFT));
	}

	@Test
	public void nothingUnlistedIsAliased()
	{
		assertEquals(-1, MonsterStatsProvider.aliasFor(NpcIds.GOBLIN));
		assertEquals(-1, MonsterStatsProvider.aliasFor(-1));
	}

	@Test
	public void noAliasPointsAtAnotherAlias()
	{
		// A chain would resolve to nothing: the lookup follows exactly one hop by design.
		for (int npcId : ALIASED)
		{
			final int target = MonsterStatsProvider.aliasFor(npcId);
			assertTrue("id " + npcId + " has no alias", target > 0);
			assertEquals("alias for " + npcId + " points at another alias", -1,
				MonsterStatsProvider.aliasFor(target));
		}
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The scythe's extra hits stopped applying because the name was matched with
 * the wiki's capitalisation and the item composition uses its own. Both of
 * these came out of a real log line: "Scythe of Vitur - Scythe, SLASH
 * AGGRESSIVE, 5 tick".
 */
public class ScytheNameTest
{
	@Test
	public void theNameTheItemCompositionActuallyReturns()
	{
		assertTrue(CombatCalc.isScythe("Scythe of Vitur"));
	}

	@Test
	public void theWikisCapitalisation()
	{
		assertTrue(CombatCalc.isScythe("Scythe of vitur"));
	}

	@Test
	public void theOrnamentKitsPutAWordInFront()
	{
		// Anchoring at the start failed for these even with the case right.
		assertTrue(CombatCalc.isScythe("Holy scythe of vitur"));
		assertTrue(CombatCalc.isScythe("Sanguine scythe of vitur"));
	}

	@Test
	public void theUnchargedForm()
	{
		assertTrue(CombatCalc.isScythe("Scythe of vitur (uncharged)"));
	}

	@Test
	public void otherWeaponsAreNotScythes()
	{
		assertFalse(CombatCalc.isScythe("Abyssal whip"));
		assertFalse(CombatCalc.isScythe("Noxious halberd"));
		assertFalse(CombatCalc.isScythe(null));
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * A scythe swing is several hits, each rolling its own accuracy and its own
 * damage, and each max is half the one before ROUNDED DOWN.
 *
 * <p>Wiki (Scythe of Vitur): "each hit will deal 50% less damage, (rounded
 * down), than the preceding hit", with a base of 47 giving 47-23-11 for a true
 * maximum of 81, and a base of 48 giving 48-24-12 for 84.
 */
public class ScytheHitsTest
{
	private static int total(int firstMax, int hits)
	{
		int total = 0;
		int max = firstMax;
		for (int hit = 0; hit < hits; hit++)
		{
			total += max;
			max = CombatCalc.nextScytheMax(max);
		}
		return total;
	}

	@Test
	public void theWikisOddExample()
	{
		assertEquals(23, CombatCalc.nextScytheMax(47));
		assertEquals(11, CombatCalc.nextScytheMax(23));
		assertEquals(81, total(47, 3));
	}

	@Test
	public void theWikisEvenExample()
	{
		assertEquals(24, CombatCalc.nextScytheMax(48));
		assertEquals(12, CombatCalc.nextScytheMax(24));
		assertEquals(84, total(48, 3));
	}

	@Test
	public void theMaxFromTheReportedFight()
	{
		// 51 max at Hespori: 51 + 25 + 12, which is 88 and not the 89 that
		// halving without rounding gives.
		assertEquals(88, total(51, 3));
	}

	@Test
	public void aTwoByTwoTargetTakesTwoOfThem()
	{
		assertEquals(76, total(51, 2));
	}

	@Test
	public void anOrdinaryWeaponIsOneHit()
	{
		assertEquals(51, total(51, 1));
	}

	@Test
	public void aLandedAttackIsAtLeastOneRollConnecting()
	{
		// The measured side counts one landed attack per swing however many of
		// the hits connect, so the expectation beside it must be the chance
		// that any did - not the sum of the chances, which reads three to one
		// against the player.
		assertEquals(0.75, CombatCalc.landChance(0.5, 2), 1e-9);
		assertEquals(0.875, CombatCalc.landChance(0.5, 3), 1e-9);
	}

	@Test
	public void oneHitIsJustItsAccuracy()
	{
		assertEquals(0.849, CombatCalc.landChance(0.849, 1), 1e-9);
	}

	@Test
	public void anUnknownAccuracyStaysUnknown()
	{
		assertEquals(-1.0, CombatCalc.landChance(-1.0, 3), 1e-9);
	}
}

package com.pvmperformance;

import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

// The table was audited against the wiki's Special attacks page on 2026-08-26,
// which found it held 21 of the specials that modify a roll. These are the
// invariants that keep the other fifty honest.
public class SpecialAttackTableTest
{
	private static final double EPSILON = 1e-9;

	/**
	 * Two weapons sharing an id means the second is unreachable: the lookup is a
	 * map keyed on the id, so the later constant silently overwrites the earlier
	 * and one weapon simply never gets its special. A green build hides it
	 * entirely, which is why this is worth a test with seventy-odd entries.
	 */
	@Test
	public void noTwoWeaponsShareAnItemId()
	{
		final Map<Integer, SpecialAttack> byId = new HashMap<>();
		for (SpecialAttack spec : SpecialAttack.values())
		{
			for (int id : spec.getItemIds())
			{
				final SpecialAttack clash = byId.put(id, spec);
				assertNull(spec.name() + " shares id " + id
					+ " with " + (clash == null ? "" : clash.name()), clash);
			}
		}
	}

	/** Every constant is findable through the lookup the plugin actually uses. */
	@Test
	public void everyConstantIsReachableThroughTheLookup()
	{
		for (SpecialAttack spec : SpecialAttack.values())
		{
			assertTrue(spec.name(), spec.getItemIds().length > 0);
			for (int id : spec.getItemIds())
			{
				assertEquals(spec.name(), spec, SpecialAttack.forItem(id));
			}
		}
	}

	/** A special with a fixed roll owes nothing to the player's max hit. */
	@Test
	public void fixedDamageSpecialsCarryTheirOwnCeiling()
	{
		assertEquals(150, SpecialAttack.DAWNBRINGER.fixedMax());
		assertEquals(25, SpecialAttack.DRAGONFIRE_SHIELD.fixedMax());
		assertEquals(15, SpecialAttack.ANCIENT_WYVERN_SHIELD.fixedMax());
		for (SpecialAttack spec : SpecialAttack.values())
		{
			assertEquals(spec.name(), spec.fixedMax() > 0, spec.hasFixedDamage());
		}
		// Only Pulsate is exempt from a cap; the shields are not.
		assertTrue(SpecialAttack.DAWNBRINGER.ignoresDamageCap());
		assertTrue(!SpecialAttack.DRAGONFIRE_SHIELD.ignoresDamageCap());
	}

	/**
	 * Hammer Blow rolls "up to max roll -5, plus 5", which is a floor of five
	 * hitpoints rather than a share of the max - the one case minFraction cannot
	 * express.
	 */
	@Test
	public void theGraniteHammerHasAFlatFloorRatherThanAShare()
	{
		assertEquals(5, SpecialAttack.GRANITE_HAMMER.flatMinimum());
		assertEquals(0.0, SpecialAttack.GRANITE_HAMMER.minFraction(), EPSILON);
		for (SpecialAttack spec : SpecialAttack.values())
		{
			assertTrue(spec.name(), spec.flatMinimum() >= 0);
		}
		// A max of 40 with a floor of 5 averages 22.5, not 20.
		final double expected = CombatCalc.specAverage(new int[]{40}, 1.0, 0.0, 5, Integer.MAX_VALUE);
		assertEquals(22.5, expected, EPSILON);
	}

	/** A flat floor above the max must not invert the roll. */
	@Test
	public void aFlatFloorAboveTheMaxIsClampedToIt()
	{
		final double expected = CombatCalc.specAverage(new int[]{3}, 1.0, 0.0, 5, Integer.MAX_VALUE);
		assertEquals(3.0, expected, EPSILON);
	}

	/**
	 * The crimson kisten is a binomial, not a cascade: all four rolls are made
	 * and the number that SUCCEED picks the damage band.
	 */
	@Test
	public void theCrimsonKistenIsABinomialNotACascade()
	{
		assertTrue(SpecialAttack.CRIMSON_KISTEN.binomialAccuracy());
		assertTrue(!SpecialAttack.CRIMSON_KISTEN.cascadingAccuracy());
		final int normalMax = 50;
		// All four connect: 130-170% of the max, averaging 150%.
		assertEquals(1.5 * normalMax,
			CombatCalc.crimsonKistenAverage(normalMax, 1.0, Integer.MAX_VALUE), 1.0);
		// None connect: the special deals nothing at all.
		assertEquals(0.0, CombatCalc.crimsonKistenAverage(normalMax, 0.0, Integer.MAX_VALUE), EPSILON);
	}

	/** More accuracy is always worth more damage, at every step. */
	@Test
	public void theCrimsonKistenRisesWithAccuracy()
	{
		double previous = -1;
		for (double accuracy = 0.0; accuracy <= 1.0; accuracy += 0.1)
		{
			final double value = CombatCalc.crimsonKistenAverage(50, accuracy, Integer.MAX_VALUE);
			assertTrue(value > previous);
			previous = value;
		}
	}

	/**
	 * The weapons whose ids are nothing like their names. Each was resolved from
	 * the wiki's item id and looked up by NUMBER; a wrong-but-existing name
	 * compiles and silently does nothing, which is the whole reason for the rule.
	 */
	@Test
	public void theWeaponsWithMisleadingGamevalNamesAreAllPresent()
	{
		for (SpecialAttack spec : new SpecialAttack[]{
			SpecialAttack.BURNING_CLAWS,      // BONE_CLAWS
			SpecialAttack.DAWNBRINGER,        // VERZIK_SPECIAL_WEAPON
			SpecialAttack.DRAGON_SWORD,       // DRAGON_SHORTSWORD
			SpecialAttack.ARMADYL_CROSSBOW,   // ACB
			SpecialAttack.THE_DOGSWORD,       // ECHO_GODSWORD
			SpecialAttack.SUNLIGHT_SPEAR,     // WEAPON_OF_SOL
			SpecialAttack.SEERCULL,           // DAGANOTH_CAVE_MAGIC_SHORTBOW
			SpecialAttack.BLUE_MOON_SPEAR,    // FROSTMOON_SPEAR
			SpecialAttack.ZARYTE_CROSSBOW,    // ZARYTE_XBOW
			SpecialAttack.BRINE_SABRE,        // OLAF2_BRINE_SABRE
			SpecialAttack.ACCURSED_SCEPTRE,   // WILD_CAVE_ACCURSED_CHARGED
			SpecialAttack.URSINE_CHAINMACE,   // WILD_CAVE_URSINE_CHARGED
			SpecialAttack.SOULREAPER_AXE,     // SOULREAPER
		})
		{
			assertNotNull(spec.name(), spec.getDisplayName());
			assertTrue(spec.name(), spec.getAttackRollMultiplier() > 0);
		}
	}

	/**
	 * The six specials that cannot miss. Everything else must carry a usable
	 * attack roll multiplier instead.
	 */
	@Test
	public void theGuaranteedHitsAreTheOnesThatShouldBe()
	{
		int guaranteed = 0;
		for (SpecialAttack spec : SpecialAttack.values())
		{
			if (spec.alwaysHits())
			{
				guaranteed++;
			}
		}
		// Voidwaker, Dawnbringer, magic longbow (which carries the comp bow),
		// Seercull and the sunlight spear.
		assertEquals(5, guaranteed);
		assertTrue(SpecialAttack.VOIDWAKER.alwaysHits());
		assertTrue(SpecialAttack.SEERCULL.alwaysHits());
		assertTrue(!SpecialAttack.ARMADYL_GODSWORD.alwaysHits());
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import net.runelite.api.EquipmentInventorySlot;
import org.junit.Test;

/**
 * A loadout must be swappable without disturbing what it was made from, since a
 * search walks candidates by making them from one another and would otherwise
 * corrupt the very thing it is comparing against.
 */
public class LoadoutTest
{
	private static final int WHIP = 4151;
	private static final int SCYTHE = 22325;

	@Test
	public void anEmptyLoadoutHasNothingInAnySlot()
	{
		final Loadout empty = Loadout.worn(null, null);
		assertEquals(-1, empty.id(EquipmentInventorySlot.WEAPON));
		assertEquals(-1, empty.id(EquipmentInventorySlot.HEAD));
	}

	@Test
	public void swappingASlotLeavesTheOriginalAlone()
	{
		final Loadout worn = Loadout.worn(null, null);
		final Loadout swapped = worn.with(EquipmentInventorySlot.WEAPON, WHIP);
		assertEquals(WHIP, swapped.id(EquipmentInventorySlot.WEAPON));
		assertEquals(-1, worn.id(EquipmentInventorySlot.WEAPON));
	}

	@Test
	public void swapsCompoundWithoutTreadingOnEachOther()
	{
		final Loadout both = Loadout.worn(null, null)
			.with(EquipmentInventorySlot.WEAPON, WHIP)
			.with(EquipmentInventorySlot.HEAD, SCYTHE);
		assertEquals(WHIP, both.id(EquipmentInventorySlot.WEAPON));
		assertEquals(SCYTHE, both.id(EquipmentInventorySlot.HEAD));
	}

	@Test
	public void swappingForWhatIsAlreadyThereCostsNothing()
	{
		final Loadout worn = Loadout.worn(null, null).with(EquipmentInventorySlot.WEAPON, WHIP);
		assertSame(worn, worn.with(EquipmentInventorySlot.WEAPON, WHIP));
		assertNotSame(worn, worn.with(EquipmentInventorySlot.WEAPON, SCYTHE));
	}

	/**
	 * The worn loadout is rebuilt every tick, so two separate objects holding
	 * the same gear is the normal case. Comparing them by reference marked
	 * every attack after a switch as having missed one.
	 */
	@Test
	public void twoLoadoutsHoldingTheSameGearAreTheSameGear()
	{
		final Loadout one = Loadout.worn(null, null).with(EquipmentInventorySlot.WEAPON, WHIP);
		final Loadout other = Loadout.worn(null, null).with(EquipmentInventorySlot.WEAPON, WHIP);
		assertNotSame(one, other);
		assertTrue(one.sameItems(other));
	}

	@Test
	public void oneSlotApartIsNotTheSameGear()
	{
		final Loadout worn = Loadout.worn(null, null).with(EquipmentInventorySlot.WEAPON, WHIP);
		assertFalse(worn.sameItems(worn.with(EquipmentInventorySlot.HEAD, SCYTHE)));
		assertFalse(worn.sameItems(null));
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The scaling arithmetic, which is the part worth testing: it is transcribed
 * from elsewhere, it is invisible when wrong, and every expected figure in a
 * raid rests on it.
 */
public class RaidScalingTest
{
	private static final double CM = 1.5;
	private static final double NONE = 1.0;

	@Test
	public void tombsAddsTwoPercentPerFiveRaidLevels()
	{
		assertEquals(80, RaidScaling.tombs(80, 0));
		// 44% at 110 rather than 44.8%: the raid level is counted in whole fives.
		assertEquals(80 * 144 / 100, RaidScaling.tombs(80, 110));
		assertEquals(112, RaidScaling.tombs(80, 100));   // +40%
		assertEquals(176, RaidScaling.tombs(80, 300));   // +120%
		assertEquals(240, RaidScaling.tombs(80, 500));   // +200%
	}

	@Test
	public void tombsCountsRaidLevelsInWholeFives()
	{
		// 104 and 100 are the same raid for scaling; 105 is not.
		assertEquals(RaidScaling.tombs(150, 100), RaidScaling.tombs(150, 104));
		assertTrue(RaidScaling.tombs(150, 105) > RaidScaling.tombs(150, 104));
	}

	@Test
	public void chambersLeavesASoloMaxedRaiderAlone()
	{
		// 99 hitpoints and one player is the identity case: the hitpoints term
		// saturates and the party term contributes nothing.
		assertEquals(205, RaidScaling.chambers(205, 1, 99, NONE));
		assertEquals(175, RaidScaling.chambers(175, 1, 99, NONE));
	}

	@Test
	public void chambersRaisesLevelsWithPartySize()
	{
		assertTrue(RaidScaling.chambers(205, 5, 99, NONE) > RaidScaling.chambers(205, 1, 99, NONE));
		assertTrue(RaidScaling.chambers(205, 15, 99, NONE) > RaidScaling.chambers(205, 5, 99, NONE));
	}

	@Test
	public void chambersLowersLevelsWithTheHitpointsTerm()
	{
		assertTrue(RaidScaling.chambers(205, 1, 50, NONE) < RaidScaling.chambers(205, 1, 99, NONE));
		assertTrue(RaidScaling.chambers(205, 1, 1, NONE) < RaidScaling.chambers(205, 1, 50, NONE));
		// The lowest the term reaches is 55/99, and it is already there at 1
		// hitpoint, the clamp guarding it never binds. Written down because it
		// is easy to read the clamp as doing more than it does.
		assertEquals(205 * 55 / 99, RaidScaling.chambers(205, 1, 1, NONE));
		assertEquals(RaidScaling.chambers(205, 1, 1, NONE), RaidScaling.chambers(205, 1, 2, NONE));
	}

	@Test
	public void tektonInAFiveManChallengeModeRaid()
	{
		// Checked against the source this was transcribed from.
		assertEquals(287, RaidScaling.chambers(205, 5, 99, 1.35));
	}

	@Test
	public void challengeModeMultipliersAreNotUniform()
	{
		assertEquals(1.5, RaidScaling.defenceMultiplier(true, 5, "Vasa Nistirio"), 0.0001);
		// Tekton takes less, and less again in a small team.
		assertEquals(1.2, RaidScaling.defenceMultiplier(true, 3, "Tekton"), 0.0001);
		assertEquals(1.35, RaidScaling.defenceMultiplier(true, 4, "Tekton"), 0.0001);
		// The glowing crystal's defence is not raised at all.
		assertEquals(1.0, RaidScaling.defenceMultiplier(true, 5, "Glowing crystal"), 0.0001);
		// None of it applies outside challenge mode.
		assertEquals(1.0, RaidScaling.defenceMultiplier(false, 5, "Tekton"), 0.0001);
		assertEquals(1.0, RaidScaling.defenceMultiplier(false, 5, null), 0.0001);
	}

	@Test
	public void everyStepFloorsAndTheOrderIsKept()
	{
		// Applying the multiplier before the party term instead of after gives a
		// different answer; this pins the order rather than only the value.
		final int correct = RaidScaling.chambers(205, 5, 99, CM);
		final int reordered = (int) (RaidScaling.chambers(205, 5, 99, NONE) * CM);
		assertTrue("the order of the steps must not stop mattering", correct <= reordered);
	}

	@Test
	public void olmsHandsKeepAThirdOfTheWrongStyle()
	{
		final double third = 1.0 / 3.0;
		// Right hand is the mage hand: magic goes through, nothing else does.
		assertEquals(1.0, RaidScaling.damageTaken(NpcIds.OLM_RIGHT, AttackType.MAGIC), 0.0001);
		assertEquals(third, RaidScaling.damageTaken(NpcIds.OLM_RIGHT, AttackType.SLASH), 0.0001);
		assertEquals(third, RaidScaling.damageTaken(NpcIds.OLM_RIGHT, AttackType.RANGED), 0.0001);
		// Left hand is the melee hand, and takes any melee style.
		assertEquals(1.0, RaidScaling.damageTaken(NpcIds.OLM_LEFT, AttackType.CRUSH), 0.0001);
		assertEquals(third, RaidScaling.damageTaken(NpcIds.OLM_LEFT, AttackType.MAGIC), 0.0001);
	}

	@Test
	public void nightmareTotemsTakeDoubleFromMagic()
	{
		assertEquals(2.0, RaidScaling.damageTaken(NpcIds.TOTEM, AttackType.MAGIC), 0.0001);
		assertEquals(1.0, RaidScaling.damageTaken(NpcIds.TOTEM, AttackType.CRUSH), 0.0001);
	}

	@Test
	public void everythingElseTakesWhatItIsGiven()
	{
		assertEquals(1.0, RaidScaling.damageTaken(-1, AttackType.MAGIC), 0.0001);
		assertEquals(1.0, RaidScaling.damageTaken(NpcIds.GOBLIN, AttackType.SLASH), 0.0001);
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

// Expected dps exists to answer the one question the average hit cannot: which
// of two setups is better when they swing at different speeds. It is built from
// the weapon's own cooldown rather than from a clock, so it owes nothing to the
// fight timer.
public class ExpectedDpsTest
{
	private static final double EPSILON = 1e-9;

	/** A tick is 0.6 seconds, so a 4 tick weapon attacks every 2.4. */
	@Test
	public void itIsTheAverageHitOverTheWeaponsCooldown()
	{
		assertEquals(10.0 / 2.4, CombatCalc.dpsFrom(10.0, 4), EPSILON);
		assertEquals(10.0 / 1.8, CombatCalc.dpsFrom(10.0, 3), EPSILON);
		// A blowpipe on rapid: every two ticks, so 1.2 seconds.
		assertEquals(5.0 / 1.2, CombatCalc.dpsFrom(5.0, 2), EPSILON);
	}

	/**
	 * The case the line is on the overlay for. A scythe hits far harder per swing
	 * than a blowpipe and still loses on sustained damage, which is invisible if
	 * you only compare average hits.
	 */
	@Test
	public void aBiggerAverageHitOnASlowerWeaponCanBeWorse()
	{
		final double slowHardHitter = CombatCalc.dpsFrom(12.0, 5);
		final double fastLightHitter = CombatCalc.dpsFrom(6.0, 2);
		assertTrue(fastLightHitter > slowHardHitter);
		// And the same weapon sped up is strictly better, which is the sanity
		// check that the speed is dividing rather than multiplying.
		assertTrue(CombatCalc.dpsFrom(10.0, 3) > CombatCalc.dpsFrom(10.0, 4));
	}

	/** No figure in means no figure out; -1 is how the overlay knows to hide it. */
	@Test
	public void noAverageHitMeansNoDps()
	{
		assertEquals(-1, CombatCalc.dpsFrom(-1, 4), EPSILON);
		assertEquals(-1, CombatCalc.dpsFrom(10.0, 0), EPSILON);
		assertEquals(-1, CombatCalc.dpsFrom(10.0, -2), EPSILON);
	}

	/** A zero average hit is a real answer, not a missing one. */
	@Test
	public void aZeroAverageHitIsZeroDpsRatherThanNoFigure()
	{
		assertEquals(0.0, CombatCalc.dpsFrom(0.0, 4), EPSILON);
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import org.junit.Test;

/**
 * Void scales the EFFECTIVE LEVEL and truncates there, before the max hit is
 * worked out from it. Multiplying the finished max hit instead is the same
 * boost and a different number, because the two round in different places - a
 * blowpipe in elite void read 33 where the game gives 34.
 *
 * <p>The arithmetic is checked here rather than the wiring, since the wiring
 * needs a client. Each case is the two orders side by side on the same input.
 */
public class VoidScalingTest
{
	/** The game's order: scale the level, truncate, then take the max hit from it. */
	private static int levelFirst(int effectiveLevel, int strengthBonus, int numerator, int denominator)
	{
		return CombatCalc.maxHitFromStrength(effectiveLevel * numerator / denominator, strengthBonus);
	}

	/** What it used to do: take the max hit, then multiply and truncate. */
	private static int maxHitFirst(int effectiveLevel, int strengthBonus, double multiplier)
	{
		return (int) (CombatCalc.maxHitFromStrength(effectiveLevel, strengthBonus) * multiplier);
	}

	@Test
	public void theTwoOrdersDisagreeAndTheLevelOneIsTheGames()
	{
		// A blowpipe with dragon darts: 112 ranged with rigour and the accurate style is an effective 120ish, and the
		// ranged strength bonus of the dart plus the pipe is in the high twenties. The exact numbers matter less than that
		// the two orders differ at all, which is the whole bug.
		final int effective = 120;
		final int strengthBonus = 60;
		assertNotEquals(levelFirst(effective, strengthBonus, 9, 8),
			maxHitFirst(effective, strengthBonus, 1.125));
	}

	@Test
	public void eliteRangedIsNineEighthsOfTheLevel()
	{
		// trunc(120 * 9 / 8) = 135, and the max hit follows from that.
		assertEquals(CombatCalc.maxHitFromStrength(135, 60), levelFirst(120, 60, 9, 8));
	}

	@Test
	public void regularVoidIsElevenTenthsOfTheLevel()
	{
		// trunc(120 * 11 / 10) = 132.
		assertEquals(CombatCalc.maxHitFromStrength(132, 60), levelFirst(120, 60, 11, 10));
	}

	@Test
	public void eliteBeatsRegularOnRangedAndNotByRounding()
	{
		// 9/8 against 11/10 is a real gap at every level, not a rounding artefact at one.
		for (int level = 80; level <= 140; level++)
		{
			assertEquals("elite must never be worse at level " + level, true,
				levelFirst(level, 60, 9, 8) >= levelFirst(level, 60, 11, 10));
		}
	}

	@Test
	public void truncationHappensAtTheLevelAndNotAfterIt()
	{
		// 99 * 11 / 10 is 108.9, which the game reads as 108. Rounding it to 109 instead would carry a point of max hit
		// into a figure that is then compared against measured damage.
		assertEquals(108, 99 * 11 / 10);
		assertEquals(111, 99 * 9 / 8);
	}
}

