		assertEquals(0, DefenceDrainCap.floor(NpcIds.DOOM, 10));
	}
}

package com.pvmperformance;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.EquipmentInventorySlot;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import org.junit.Test;

/**
 * The search is the one part of gear switching that needs no Client: it takes
 * what a loadout is worth as an argument. These use a scorer where a higher
 * item id is simply better, so the arithmetic never enters into it.
 */
public class GearSearchTest
{
	// An empty loadout needs no ItemManager as long as nothing asks for a name,
	// and the scorer here asks only for ids.
	private static Loadout empty()
	{
		return Loadout.worn(null, null);
	}

	private static GearSearch.Score higherIdIsBetter()
	{
		return gear ->
		{
			double total = 0;
			for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
			{
				total += Math.max(0, gear.id(slot));
			}
			return total;
		};
	}

	private static List<GearSearch.Candidate> carrying(EquipmentInventorySlot slot, int itemId)
	{
		return Collections.singletonList(new GearSearch.Candidate(slot, itemId));
	}

	@Test
	public void wornIsReturnedByIdentityWhenNothingBeatsIt()
	{
		final Loadout worn = empty().with(EquipmentInventorySlot.HEAD, 500);
		// The search does not copy when it has nothing to say. Callers must
		// still compare by sameItems, not by reference — the worn loadout is
		// rebuilt every tick, so this identity does not survive one.
		assertSame(worn, GearSearch.best(worn, carrying(EquipmentInventorySlot.HEAD, 100),
			false, higherIdIsBetter()));
	}

	@Test
	public void aBetterItemIsSwappedIn()
	{
		final Loadout worn = empty().with(EquipmentInventorySlot.HEAD, 100);
		final Loadout best = GearSearch.best(worn, carrying(EquipmentInventorySlot.HEAD, 500),
			false, higherIdIsBetter());
		assertEquals(500, best.id(EquipmentInventorySlot.HEAD));
	}

	@Test
	public void severalSlotsImproveTogether()
	{
		final Loadout worn = empty()
			.with(EquipmentInventorySlot.HEAD, 100)
			.with(EquipmentInventorySlot.BODY, 100);
		final Loadout best = GearSearch.best(worn, Arrays.asList(
			new GearSearch.Candidate(EquipmentInventorySlot.HEAD, 500),
			new GearSearch.Candidate(EquipmentInventorySlot.BODY, 700)),
			false, higherIdIsBetter());
		assertEquals(500, best.id(EquipmentInventorySlot.HEAD));
		assertEquals(700, best.id(EquipmentInventorySlot.BODY));
	}

	@Test
	public void theWeaponIsNeverJudged()
	{
		final Loadout worn = empty().with(EquipmentInventorySlot.WEAPON, 100);
		// The whole point of pinning the weapon: a better one in the bag is not
		// a missed switch, because which weapon to bring is not being scored.
		assertSame(worn, GearSearch.best(worn, carrying(EquipmentInventorySlot.WEAPON, 900),
			false, higherIdIsBetter()));
	}

	@Test
	public void aTwoHanderLeavesNoShieldSlotToFill()
	{
		final Loadout worn = empty().with(EquipmentInventorySlot.WEAPON, 100);
		// Advice the game would not let the player take is not advice.
		assertSame(worn, GearSearch.best(worn, carrying(EquipmentInventorySlot.SHIELD, 900),
			true, higherIdIsBetter()));
	}

	@Test
	public void aShieldIsJudgedWhenTheWeaponIsOneHanded()
	{
		final Loadout worn = empty().with(EquipmentInventorySlot.WEAPON, 100);
		final Loadout best = GearSearch.best(worn, carrying(EquipmentInventorySlot.SHIELD, 900),
			false, higherIdIsBetter());
		assertEquals(900, best.id(EquipmentInventorySlot.SHIELD));
	}

	@Test
	public void anItemAlreadyWornInThatSlotIsNotASwitch()
	{
		final Loadout worn = empty().with(EquipmentInventorySlot.HEAD, 500);
		assertSame(worn, GearSearch.best(worn, carrying(EquipmentInventorySlot.HEAD, 500),
			false, higherIdIsBetter()));
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import java.util.Collections;
import org.junit.Test;

// Every row must have as many columns as the header names, at every level.
public class CsvRowTest
{
	private static final int COLUMNS = PvmPerformancePlugin.CSV_HEADER.trim().split(",", -1).length;

	private static Fight fight()
	{
		final Fight f = new Fight("Some \"quoted\" npc", NpcIds.GOBLIN, 1, 100, 0L, RaidType.TOMBS_OF_AMASCUT, 2);
		f.recordAttackMade(true);
		f.recordAttackResolved(true, true, 10, 12);
		f.recordDamageDealt(7, 600L, true);
		f.recordExpected(20, 0.75, 6.5);
		f.recordTickLost(false);
		f.end(true, 1200L);
		return f;
	}

	private static int columns(String row)
	{
		// Quoted fields hold no commas here, so a plain split is enough.
		return row.trim().split(",", -1).length;
	}

	@Test
	public void theHeaderNamesEveryColumnOnce()
	{
		// attempts and targets are both there now: one throw of chinchompas is one attempt and several targets.
		assertEquals(29, COLUMNS);
	}

	@Test
	public void aPhaseRowMatchesTheHeader()
	{
		assertEquals(COLUMNS, columns("fight,x,1,\"room\"," + PvmPerformancePlugin.csvRow(fight())));
	}

	@Test
	public void aRoomRowMatchesTheHeader()
	{
		final Encounter room = new Encounter("Kephri", RaidType.TOMBS_OF_AMASCUT, 0L);
		room.add(fight());
		assertEquals(COLUMNS, columns(PvmPerformancePlugin.csvRoomRow("Tombs of Amascut", 2, room)));
	}

	@Test
	public void aRaidRowMatchesTheHeader()
	{
		final Encounter room = new Encounter("Kephri", RaidType.TOMBS_OF_AMASCUT, 0L);
		room.add(fight());
		assertEquals(COLUMNS,
			columns(PvmPerformancePlugin.csvRaidRow("Tombs of Amascut", 2, Collections.singletonList(room))));
	}

	@Test
	public void aRoomWithNothingToReportStillFillsItsColumns()
	{
		// An empty room divides by zero in several places if it is not careful.
		final Encounter empty = new Encounter("Vanguards", null, 0L);
		assertEquals(COLUMNS, columns(PvmPerformancePlugin.csvRoomRow(null, 0, empty)));
	}

	@Test
	public void quotesInAnNpcNameDoNotSplitTheRow()
	{
		assertEquals(COLUMNS, columns("fight,,,\"\"," + PvmPerformancePlugin.csvRow(fight())));
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The tables, where the errors are transcription rather than arithmetic: an id
 * in the wrong room, or one that got a name-based guess instead of a checked
 * number.
 */
public class EncounterGroupTest
{
	@Test
	public void nylocasGroupByStyleAndNotBySize()
	{
		assertEquals("Nylocas (melee)", EncounterGroup.of(NpcIds.NYLO_MELEE_SMALL));
		assertEquals("Nylocas (melee)", EncounterGroup.of(NpcIds.NYLO_MELEE_BIG_FIGHTING));
		assertTrue(EncounterGroup.sameGroup(NpcIds.NYLO_MELEE_SMALL, NpcIds.NYLO_MELEE_BIG_FIGHTING));
		// Different colours are different jobs and must not merge.
		assertFalse(EncounterGroup.sameGroup(NpcIds.NYLO_MELEE_SMALL, NpcIds.NYLO_MAGIC_SMALL));
	}

	@Test
	public void aNylocasThatHasSettledStillBelongsToItsColour()
	{
		// The bug this is here to stop coming back: only the incoming forms were
		// listed, and a nylocas changes id when it reaches a pillar and turns to
		// fight, which is when most of them are killed.
		assertEquals(EncounterGroup.of(NpcIds.NYLO_MELEE_SMALL),
			EncounterGroup.of(NpcIds.NYLO_MELEE_BIG_FIGHTING));
	}

	@Test
	public void kephrisRoomIsHersAndHerScarabsDoNotScore()
	{
		assertEquals("Kephri", EncounterGroup.of(NpcIds.KEPHRI));
		assertEquals("Kephri", EncounterGroup.of(NpcIds.KEPHRI_SCARAB));
		// Grouped so the time counts, unscored so the guaranteed max hits do not.
		assertTrue(EncounterGroup.isUnscored(NpcIds.KEPHRI_SCARAB));
		assertFalse(EncounterGroup.isUnscored(NpcIds.KEPHRI));
	}

	@Test
	public void anUnscoredNpcIsAlwaysGroupedWithSomething()
	{
		// Unscored without a group would be worse than either: the time spent on
		// it would be booked against the boss as ticks lost.
		for (int npcId = 0; npcId < 30000; npcId++)
		{
			if (EncounterGroup.isUnscored(npcId))
			{
				assertNotNull("unscored npc " + npcId + " needs a group",
					EncounterGroup.of(npcId));
			}
		}
	}

	@Test
	public void zebaksJugsAreNotTrackedAtAll()
	{
		assertTrue(EncounterGroup.isIgnored(NpcIds.ZEBAK_JUG));
		assertNull(EncounterGroup.of(NpcIds.ZEBAK_JUG));
	}

	@Test
	public void aDormantTotemCannotBeFought()
	{
		assertTrue(EncounterGroup.isUnattackable(NpcIds.TOTEM_DORMANT));
		assertFalse(EncounterGroup.isUnattackable(NpcIds.TOTEM));
	}

	@Test
	public void bothNightmaresShareTheirTotemsButNotTheirBosses()
	{
		assertTrue(EncounterGroup.isNightmareTotem(NpcIds.TOTEM));
		// A totem names no boss; the boss in the room decides.
		assertNull(EncounterGroup.nightmareBossName(NpcIds.TOTEM));
		assertEquals("Phosani's Nightmare", EncounterGroup.nightmareBossName(NpcIds.PHOSANI));
		assertEquals("The Nightmare", EncounterGroup.nightmareBossName(NpcIds.NIGHTMARE));
	}

	@Test
	public void ordinaryMonstersAreNotInAnyTable()
	{
		assertNull(EncounterGroup.of(NpcIds.GOBLIN));
		assertFalse(EncounterGroup.isIgnored(NpcIds.GOBLIN));
		assertFalse(EncounterGroup.isUnscored(NpcIds.GOBLIN));
		assertFalse(EncounterGroup.isUnattackable(NpcIds.GOBLIN));
	}

	@Test
	public void olmsHeadIsNotGroupedWithItsHands()
	{
		assertFalse(EncounterGroup.sameGroup(NpcIds.OLM_HEAD, NpcIds.OLM_LEFT));
		assertTrue(EncounterGroup.sameGroup(NpcIds.OLM_LEFT, NpcIds.OLM_RIGHT));
	}

	@Test
	public void theWardensEnergySiphonsAreAMechanicAndNotAFight()
	{
		// The skulls in phase two. Each was opening its own fight and then holding the overlay, in the middle of a raid.
		assertTrue(EncounterGroup.isIgnored(net.runelite.api.gameval.NpcID.TOA_WARDENS_ENERGY));
		// The wardens themselves are still fought.
		assertFalse(EncounterGroup.isIgnored(net.runelite.api.gameval.NpcID.TOA_WARDEN_ELIDINIS_PHASE2_MAGE));
		assertFalse(EncounterGroup.isIgnored(net.runelite.api.gameval.NpcID.TOA_WARDEN_TUMEKEN_PHASE2_MAGE));
	}

	@Test
	public void theHueycoatlsSeerIsSceneryAndIsNeverTracked()
	{
		// It stands in that fight and is not part of it. A single point of damage lands on it on the phase change and
		// reads as the player's, which was enough to open a fight, book an attack and count a kill - nine of each in one
		// trip. Named here rather than left to the fightable test, which can only ask the game and was got past once.
		assertTrue(EncounterGroup.isIgnored(net.runelite.api.gameval.NpcID.HUEY_SEER));
		// The snake itself is still tracked, in every part.
		assertFalse(EncounterGroup.isIgnored(net.runelite.api.gameval.NpcID.HUEY_HEAD));
		assertFalse(EncounterGroup.isIgnored(net.runelite.api.gameval.NpcID.HUEY_BODY_PART));
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

// The attack roll is floored at zero, so a deeply negative equipment bonus
// reads as "will not hit" rather than as no figure at all.
public class AttackRollTest
{
	/** The case that was seen in game: a spell thrown from a whip setup. */
	@Test
	public void flooredWhenTheEquipmentBonusIsBelowMinusSixtyFour()
	{
		// Magic level 112 with no prayer, and a melee loadout's magic attack.
		assertEquals(0, CombatCalc.attackRoll(121, -70, 1.0));
		assertEquals(0, CombatCalc.attackRoll(121, -65, 1.0));
	}

	/** Exactly -64 is the boundary, and is zero without needing the floor. */
	@Test
	public void isZeroAtTheBoundary()
	{
		assertEquals(0, CombatCalc.attackRoll(121, -64, 1.0));
	}

	/** Everything above the boundary is untouched by the floor. */
	@Test
	public void isUnchangedForAnOrdinaryLoadout()
	{
		assertEquals(121 * 4, CombatCalc.attackRoll(121, -60, 1.0));
		assertEquals(121 * 174, CombatCalc.attackRoll(121, 110, 1.0));
		// The gear multiplier still applies; salve (i) on a magic loadout.
		assertEquals((int) (121 * 174 * 1.15), CombatCalc.attackRoll(121, 110, 1.15));
	}

	/**
	 * The floored roll has to survive the hit chance formula as a real
	 * probability, since that is what the negative one failed to do.
	 */
	@Test
	public void producesAUsableHitChance()
	{
		for (int bonus = -120; bonus <= 200; bonus += 1)
		{
			final int attRoll = CombatCalc.attackRoll(121, bonus, 1.0);
			assertTrue("roll went negative at bonus " + bonus, attRoll >= 0);
		}
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * A damage cap is not a smaller max hit, and the difference is the whole reason
 * this is its own method. Every roll above the cap collapses onto it, so the
 * average sits near the cap rather than near half of it — treating the
 * Hueycoatl's tail as a nine max hit would understate the damage by nearly half.
 */
public class CappedAverageTest
{
	private static final double EXACT = 1e-9;

	@Test
	public void theCapIsWhatIsLEFTAndNotAnAverageOfIt()
	{
		// The point the cap is often misread on. A 60 max against 10 remaining does not expect 10, and does not expect the
		// uncapped 30: the rolls under 10 still land where they fall and everything from 10 up becomes a 10.
		//   rolls 0..9   -> 0..9      sum 45
		//   rolls 10..60 -> 10 each   sum 510
		assertEquals(555.0 / 61.0, CombatCalc.cappedAverage(60, 10), EXACT);
		assertEquals(9.10, CombatCalc.cappedAverage(60, 10), 0.01);
		// And it can never exceed what is left, whatever the max hit is.
		for (int max = 10; max <= 120; max += 10)
		{
			assertEquals("a cap of 10 must hold at max " + max, true, CombatCalc.cappedAverage(max, 10) <= 10.0);
		}
	}

	@Test
	public void overkillIsTheSameArithmeticAsADamageCap()
	{
		// What a killing blow is worth. An attack with a 60 max against a target on 3 hitpoints cannot deal more than 3,
		// so the expectation is the capped average and not half of 60 - the difference is what was being counted as damage
		// the setup failed to produce, once per kill.
		assertEquals(30.0, CombatCalc.cappedAverage(60, 60), EXACT);
		// Rolls 0..3 keep their value, 4..60 all land on 3: (6 + 57*3) / 61.
		assertEquals(177.0 / 61.0, CombatCalc.cappedAverage(60, 3), EXACT);
		// Just under 3, where the uncapped figure said 30. Ten times over, on the last attack of every kill.
		assertEquals(2.90, CombatCalc.cappedAverage(60, 3), 0.01);
	}

	@Test
	public void aCapAboveTheMaxChangesNothing()
	{
		assertEquals(30.0, CombatCalc.cappedAverage(60, 9999), EXACT);
		assertEquals(30.0, CombatCalc.cappedAverage(60, 60), EXACT);
	}

	@Test
	public void theTailCapSitsNearTheCapAndNotNearHalfOfIt()
	{
		// Rolls 0..9 keep their value and 10..60 all land on 9:
		// (45 + 51*9) / 61.
		assertEquals(504.0 / 61.0, CombatCalc.cappedAverage(60, 9), EXACT);
		// Which is over eight, where half the cap would have been 4.5.
		assertEquals(8.26, CombatCalc.cappedAverage(60, 9), 0.01);
	}

	@Test
	public void theCrushlessTailCapIsWorseStill()
	{
		// Rolls 0..4 keep their value and 5..60 all land on 4, which is 56 of
		// them, not 57 — the count of collapsed rolls is trueMax minus cap.
		// (10 + 56*4) / 61
		assertEquals(234.0 / 61.0, CombatCalc.cappedAverage(60, 4), EXACT);
	}

	@Test
	public void aCapOfZeroLandsNothing()
	{
		assertEquals(0.0, CombatCalc.cappedAverage(60, 0), EXACT);
	}

	@Test
	public void noMaxHitIsNoDamage()
	{
		assertEquals(0.0, CombatCalc.cappedAverage(0, 9), EXACT);
		assertEquals(0.0, CombatCalc.cappedAverage(-1, 9), EXACT);
	}

	@Test
	public void aSmallerMaxRaisesTheAverageTowardsTheCap()
	{
		// The lower the true max, the fewer rolls collapse onto the cap, so a
		// weaker weapon loses proportionally less to it.
		final double strong = CombatCalc.cappedAverage(60, 9);
		final double weak = CombatCalc.cappedAverage(12, 9);
		assertEquals(true, weak < strong);
	}
}

