package com.pvmperformance;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * One throw is one attack however many it catches, and the accuracy divides by
 * what it reached rather than by what was thrown. Chinchompas into a pile of
 * adds is the case: five npcs, one throw, and three of them take damage is
 * three of five - not three of one, and not three attacks.
 */
public class AoeAttributionTest
{
	private static Fight fight()
	{
		return new Fight("target", NpcIds.GOBLIN, 1, 100, 0L, null, 0);
	}

	/** One throw at {@code caught} npcs, of which {@code landed} take damage. */
	private static Fight throwAt(int caught, int landed)
	{
		final Fight f = fight();
		f.recordAttackMade(false);
		// The one it was aimed at, which recordAttackMade already counted as a target.
		f.recordDamageDealt(landed > 0 ? 10 : 0, 0L, landed > 0);
		for (int extra = 1; extra < caught; extra++)
		{
			final boolean hit = extra < landed;
			f.recordExtraTarget(hit ? 10 : 0, 0L, true, hit);
		}
		return f;
	}

	@Test
	public void oneThrowIsOneAttackHoweverManyItCatches()
	{
		final Fight f = throwAt(5, 3);
		assertEquals("one throw", 1, f.getAttacksMade());
		assertEquals("one attempt", 1, f.getAttempts());
		assertEquals("five npcs reached", 5, f.resolvedTargets());
		assertEquals("three of them took damage", 3, f.getHits());
		assertEquals(0.6, f.accuracy(), 1e-9);
	}

	@Test
	public void everythingItCaughtLendsItsDamageToTheSameAttack()
	{
		final Fight f = throwAt(5, 3);
		assertEquals(30, f.getDamageDealt());
		// Damage divides by the THROW, not by the targets: this is what one attack is worth, which is what the expected
		// side is a sum over the same targets for.
		assertEquals(30.0, f.averageHit(), 1e-9);
	}

	@Test
	public void singleTargetCombatIsUnchanged()
	{
		// The whole point: with one target an attack, targets and attempts are the same number and every figure reads as
		// it always did.
		final Fight f = fight();
		f.recordAttackMade(false);
		f.recordDamageDealt(10, 0L, true);
		f.recordAttackMade(false);
		f.recordDamageDealt(0, 0L, false);
		assertEquals(2, f.getAttempts());
		assertEquals(2, f.resolvedTargets());
		assertEquals(1, f.getHits());
		assertEquals(0.5, f.accuracy(), 1e-9);
		assertEquals(5.0, f.averageHit(), 1e-9);
	}

	@Test
	public void aBurstOnOneNpcIsOneTarget()
	{
		// A scythe lands three splats on the same enemy and they are one blow, so the second and third bring damage and
		// nothing else - the same rule that already makes them one landed attack.
		final Fight f = fight();
		f.recordAttackMade(false);
		f.recordDamageDealt(10, 0L, true);
		f.recordExtraTarget(6, 0L, true, true);
		f.recordExtraTarget(3, 0L, false, false);
		f.recordExtraTarget(1, 0L, false, false);
		assertEquals(2, f.resolvedTargets());
		assertEquals(2, f.getHits());
		assertEquals(20, f.getDamageDealt());
	}

	@Test
	public void aFightFromAnOlderHistoryFileStillReadsItsAccuracy()
	{
		// Gson fills the fields it finds and leaves the rest at zero, so a kill saved before targets existed comes back
		// with none. Divided by that it would report 0% accuracy for every fight already on disk.
		final Fight old = fight();
		old.recordAttackMade(false);
		old.recordAttackMade(false);
		old.recordDamageDealt(10, 0L, true);
		final Gson gson = new Gson();
		final Fight loaded = gson.fromJson(
			gson.toJson(old).replaceAll("\"targets\":[0-9]+,?", ""), Fight.class);
		assertEquals(2, loaded.getAttempts());
		assertEquals(2, loaded.resolvedTargets());
		assertEquals(0.5, loaded.accuracy(), 1e-9);
	}

	@Test
	public void aRoomSumsTheTargetsItsFightsReached()
	{
		final Encounter room = new Encounter("Tightrope", null, 0L);
		room.add(throwAt(5, 3));
		room.add(throwAt(4, 1));
		assertEquals(2, room.getAttempts());
		assertEquals(9, room.getTargets());
		assertEquals(4, room.getHits());
		assertEquals(4.0 / 9.0, room.accuracy(), 1e-9);
		// And it can never read above 100%, which is what the old denominator did once hits outnumbered attacks.
		assertEquals(true, room.accuracy() <= 1.0);
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * An attack in the air when the target dies is not a miss. It cost a tick and
 * was thrown with whatever was up, so it stays in attacksMade, but it has no
 * outcome to be right or wrong about — and left in the denominator it hands
 * back a perfect kill as a failure.
 */
public class NulledAttackTest
{
	private static Fight fight()
	{
		return new Fight("target", NpcIds.GOBLIN, 1, 100, 0L, null, 0);
	}

	@Test
	public void anOrdinaryFightIsUnaffected()
	{
		final Fight f = fight();
		f.recordAttackMade(false);
		f.recordAttackMade(false);
		f.recordDamageDealt(10, 0L, true);
		assertEquals(2, f.resolvedAttempts());
		assertEquals(0.5, f.accuracy(), 1e-9);
		assertEquals(5.0, f.averageHit(), 1e-9);
	}

	@Test
	public void theKillingBlowsNeighbourDoesNotDragTheAverageDown()
	{
		// Two attacks, one landed for 10, the second nulled by the kill. Its
		// damage of nothing must not halve the average hit, because it never
		// had a target left to deal any.
		final Fight f = fight();
		f.recordAttackMade(false);
		f.recordAttackMade(false);
		f.recordDamageDealt(10, 0L, true);
		f.recordAttackNulled();
		assertEquals(1, f.resolvedAttempts());
		assertEquals(10.0, f.averageHit(), 1e-9);
	}

	@Test
	public void butItStillCountsAgainstTheAccuracy()
	{
		// Changed deliberately, on the owner's call. Nulling used to strike the
		// attack from the accuracy as well, which read as one attack that hit
		// for 10 - a flat 100%. On screen that left Hits at 13 of 17 while
		// prayed, potted and switches all read out of 18, and the odd one out
		// was the one nobody could reproduce by counting. An attack that was
		// thrown is now always in the denominator.
		final Fight f = fight();
		f.recordAttackMade(false);
		f.recordAttackMade(false);
		f.recordDamageDealt(10, 0L, true);
		f.recordAttackNulled();
		assertEquals(2, f.resolvedTargets());
		assertEquals(0.5, f.accuracy(), 1e-9);
	}

	@Test
	public void theAttackItselfStillHappened()
	{
		// It cost a tick and was thrown with whatever prayer and gear were up,
		// so the efficiency side must still see it.
		final Fight f = fight();
		f.recordAttackMade(false);
		f.recordAttackNulled();
		assertEquals(1, f.getAttacksMade());
		assertEquals(0, f.resolvedAttempts());
	}

	@Test
	public void nullingAnOrdinaryMissReadsAsBetterThanPerfect()
	{
		// Why the plugin now nulls only when the target DIED. A room of one-attack fights, each a miss whose answer
		// arrived after its fight had ended: every attempt was erased while the hits from the fights that landed stayed,
		// and the room reported more hits than attempts. A real export reads 81 hits against 80 attempts this way, which
		// is an accuracy of 101.3% and cannot happen.
		final Encounter room = new Encounter("Tightrope", null, 0L);
		final Fight landed = fight();
		landed.recordAttackMade(false);
		landed.recordDamageDealt(10, 0L, true);
		room.add(landed);
		for (int miss = 0; miss < 3; miss++)
		{
			final Fight f = fight();
			f.recordAttackMade(false);
			f.recordAttackNulled();
			room.add(f);
		}
		// What it did: three misses erased, leaving one hit against one attempt.
		assertEquals(1, room.getAttempts());
		assertEquals(1, room.getHits());
		// What it must be once a miss keeps its attempt: one hit in four.
		final Encounter fixed = new Encounter("Tightrope", null, 0L);
		final Fight hit = fight();
		hit.recordAttackMade(false);
		hit.recordDamageDealt(10, 0L, true);
		fixed.add(hit);
		for (int miss = 0; miss < 3; miss++)
		{
			final Fight f = fight();
			f.recordAttackMade(false);
			fixed.add(f);
		}
		assertEquals(4, fixed.getAttempts());
		assertEquals(1, fixed.getHits());
		assertEquals(0.25, fixed.accuracy(), 1e-9);
	}

	@Test
	public void nothingGoesNegativeIfMoreAreNulledThanMade()
	{
		final Fight f = fight();
		f.recordAttackNulled();
		f.recordAttackNulled();
		assertEquals(0, f.resolvedAttempts());
		assertEquals(0.0, f.averageHit(), 1e-9);
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Wiki (Elemental weakness): each point is worth 1% magic damage and 1% magic
 * accuracy, and it applies only to the standard spellbook's elemental ladders -
 * "strike, bolt, blast, wave, and surge spells". Ancient spells are excluded
 * outright, which is why a barrage gets none of it however weak the target is.
 */
public class ElementalWeaknessTest
{
	@Test
	public void theWholeElementalLadderCounts()
	{
		assertTrue(Spell.EARTH_STRIKE.isElement("earth"));
		assertTrue(Spell.EARTH_BOLT.isElement("earth"));
		assertTrue(Spell.EARTH_BLAST.isElement("earth"));
		assertTrue(Spell.EARTH_WAVE.isElement("earth"));
		assertTrue(Spell.EARTH_SURGE.isElement("earth"));
	}

	@Test
	public void theWrongElementGetsNothing()
	{
		// The Hueycoatl is earth 60, so a fire surge there is an ordinary cast.
		assertFalse(Spell.FIRE_SURGE.isElement("earth"));
		assertFalse(Spell.WIND_WAVE.isElement("water"));
	}

	@Test
	public void anAncientSpellIsNeverElemental()
	{
		// The case that matters most here: barraging a target with a weakness
		// must not pick the bonus up.
		assertFalse(Spell.BLOOD_BARRAGE.isElement("earth"));
		assertFalse(Spell.ICE_BARRAGE.isElement("water"));
		assertFalse(Spell.FIRE_SURGE.isElement(null));
	}

	@Test
	public void matchingIsCaseInsensitiveBothWays()
	{
		// The element comes from the monster data, which is not ours to trust
		// the casing of.
		assertTrue(Spell.WATER_SURGE.isElement("WATER"));
		assertTrue(Spell.WATER_SURGE.isElement("Water"));
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import org.junit.Test;

// Osmumten's fang rolls between 15% and 85% of the true max hit, and the
// top of that range is the max less the raised minimum, not 85% of the max.
public class FangMaxHitTest
{
	/** The two figures a real loadout was checked against in game. */
	@Test
	public void matchesTheFiguresObservedInGame()
	{
		// Stab, and the same setup on lunge, whose +3 strength lifts the true max.
		assertEquals(24, CombatCalc.fangMaxHit(28));
		assertEquals(25, CombatCalc.fangMaxHit(29));
	}

	/** The wiki's own worked example, which is the case where the two agree. */
	@Test
	public void matchesTheWikiExample()
	{
		// "if the fang's true max hit was 60, it would roll between 9 and 51"
		assertEquals(9, 60 * 15 / 100);
		assertEquals(51, CombatCalc.fangMaxHit(60));
	}

	/**
	 * The bug that was fixed, stated directly: scaling by 0.85 is a different
	 * function, and agrees only where 15% of the max happens to be whole.
	 */
	@Test
	public void differsFromScalingByPointEightFive()
	{
		assertNotEquals((int) (28 * 0.85), CombatCalc.fangMaxHit(28));
		int disagreements = 0;
		for (int max = 1; max <= 120; max++)
		{
			if ((int) (max * 0.85) != CombatCalc.fangMaxHit(max))
			{
				disagreements++;
			}
		}
		// Only the multiples of 20 agree, so the wrong figure is the common case.
		assertEquals(114, disagreements);
	}

	/** The narrowing is symmetric, which is why no average is adjusted for it. */
	@Test
	public void leavesTheAverageOnHalfTheTrueMax()
	{
		for (int max = 1; max <= 120; max++)
		{
			final int min = max * 15 / 100;
			assertEquals(max, min + CombatCalc.fangMaxHit(max));
		}
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Tick accounting and what a room does with the fights under it. The branches
 * here decide whether a player is told they wasted time, so being wrong is
 * worse than being silent.
 */
public class FightAccountingTest
{
	private static Fight fight(int npcId)
	{
		return new Fight("target", npcId, 1, 100, 0L, null, 0);
	}

	private static Fight fought(int npcId, int damage)
	{
		final Fight f = fight(npcId);
		f.recordAttackMade(true);
		f.recordAttackResolved(true, true, 10, 10);
		f.recordDamageDealt(damage, 0L, damage > 0);
		return f;
	}

	@Test
	public void nothingIsCountedBeforeTheFirstAttack()
	{
		// Walking into range is not wasted combat time.
		final Fight f = fight(NpcIds.GOBLIN);
		f.recordTickLost(false);
		f.recordTickSpent();
		assertEquals(0, f.getTicksLost());
		assertEquals(0, f.getCombatTicks());
		assertEquals(-1, f.ticksLostShare(), 0.0001);
	}

	@Test
	public void aRoomThatHasBeenFoughtInCountsItsNextFightFromTheFirstTick()
	{
		// The hole this closes. A room whose fights are one attack each - chinning a pile of adds, or a target that dies and
		// is replaced - never got past the "walking to a boss is not wasted time" exemption, because each new fight arrived
		// with nothing attacked yet. A real tightrope room booked 8 lost ticks against the 1354 that passed.
		final Fight fresh = fight(NpcIds.GOBLIN);
		fresh.recordTickLost(false, false);
		fresh.recordTickSpent(false);
		assertEquals("the FIRST fight in a room still gets the walk for free", 0, fresh.getCombatTicks());

		final Fight next = fight(NpcIds.GOBLIN);
		next.recordTickLost(false, true);
		next.recordTickSpent(true);
		assertEquals(2, next.getCombatTicks());
		assertEquals(1, next.getTicksLost());
		assertEquals(0.5, next.ticksLostShare(), 0.0001);
	}

	@Test
	public void theRoomsExemptionDoesNotDoubleCountAFightThatHasAttacked()
	{
		// Once the fight has attacked in its own right the flag changes nothing, so a room-level yes cannot inflate a fight
		// that was already counting.
		final Fight f = fought(NpcIds.GOBLIN, 5);
		f.recordTickLost(false, true);
		f.recordTickSpent(true);
		assertEquals(3, f.getCombatTicks());
		assertEquals(1, f.getTicksLost());
	}

	@Test
	public void aTickOnCooldownIsSpentAndNotLost()
	{
		final Fight f = fought(NpcIds.GOBLIN, 5);
		f.recordTickSpent();
		f.recordTickSpent();
		assertEquals(0, f.getTicksLost());
		assertEquals(3, f.getCombatTicks());
		assertEquals(0.0, f.ticksLostShare(), 0.0001);
	}

	@Test
	public void eatingIsSeparatedFromIdling()
	{
		final Fight f = fought(NpcIds.GOBLIN, 5);
		f.recordTickLost(true);
		f.recordTickLost(false);
		assertEquals(1, f.getTicksLostEating());
		assertEquals(2, f.getTicksLost());
		assertEquals(2.0 / 3.0, f.ticksLostShare(), 0.0001);
	}

	@Test
	public void anUnscoredFightLendsItsTimeButNotItsDamage()
	{
		final Encounter room = new Encounter("Kephri", null, 0L);
		final Fight boss = fought(NpcIds.KEPHRI, 40);
		final Fight scarab = fought(NpcIds.KEPHRI_SCARAB, 10);
		boss.recordTickLost(false);
		scarab.recordTickLost(false);
		room.add(boss);
		room.add(scarab);

		assertTrue("the scarab must not be scored", scarab.isScored() == false);
		// Damage, hits and attempts come from the boss alone.
		assertEquals(40, room.getDamageDealt());
		assertEquals(1, room.getAttempts());
		assertEquals(1, room.getHits());
		// Ticks come from both, so the time spent below still shows.
		assertEquals(4, room.getCombatTicks());
		assertEquals(2, room.getTicksLost());
	}

	@Test
	public void aRoomIsTheSumOfItsPhases()
	{
		final Encounter room = new Encounter("Wardens", null, 0L);
		room.add(fought(NpcIds.GOBLIN, 30));
		room.add(fought(NpcIds.GOBLIN, 20));
		assertEquals(50, room.getDamageDealt());
		assertEquals(2, room.getAttempts());
		assertEquals(25.0, room.averageHit(), 0.0001);
		assertEquals(1.0, room.accuracy(), 0.0001);
		// Both attacks were prayed and potted, so nothing was given away.
		assertEquals(1.0, room.efficiency(), 0.0001);
	}

	@Test
	public void aMissDragsTheRoomsAccuracyDownButNotItsAttempts()
	{
		final Encounter room = new Encounter("Zebak", null, 0L);
		room.add(fought(NpcIds.GOBLIN, 12));
		room.add(fought(NpcIds.GOBLIN, 0));
		assertEquals(2, room.getAttempts());
		assertEquals(1, room.getHits());
		assertEquals(0.5, room.accuracy(), 0.0001);
		assertEquals(6.0, room.averageHit(), 0.0001);
	}

	@Test
	public void aRoomOnlyCountsAsKilledIfSomethingDied()
	{
		final Encounter room = new Encounter("Akkha", null, 0L);
		final Fight f = fought(NpcIds.GOBLIN, 5);
		room.add(f);
		assertTrue(!room.isKilled());
		f.end(true, 10L);
		assertTrue(room.isKilled());
	}

	@Test
	public void aFightTakesItsGroupAndScoringFromTheTables()
	{
		assertEquals("Kephri", fight(NpcIds.KEPHRI_SCARAB).encounterName());
		assertEquals("target", fight(NpcIds.GOBLIN).encounterName());
		// A label set for a phase wins over the group it would otherwise take.
		final Fight labelled = fight(NpcIds.OLM_LEFT);
		labelled.setEncounterLabel("Great Olm (hands) - acid");
		assertEquals("Great Olm (hands) - acid", labelled.encounterName());
	}

	@Test
	public void efficiencyCanNeverExceedWhatWasAvailable()
	{
		// An ice barrage read 107%. The ratio is the setup used against the best one available, and the setup used is
		// always one of the available ones, so anything over 100% means an input to the "ideal" was under-reading - the
		// boost, in that case, since an imbued heart is not one of the two the model recognised by name.
		final Fight f = fight(NpcIds.GOBLIN);
		f.recordAttackMade(false);
		// What the booking now passes: the ideal is never below the actual.
		final double actual = 7.81;
		final double best = 7.31;
		f.recordAttackResolved(false, true, actual, Math.max(best, actual));
		assertEquals(1.0, f.efficiency(), 1e-9);
		assertTrue(f.efficiency() <= 1.0);
	}

	@Test
	public void aSetupShortOfTheIdealStillReadsShort()
	{
		// And the clamp must not flatter anyone: a real shortfall is untouched.
		final Fight f = fight(NpcIds.GOBLIN);
		f.recordAttackMade(false);
		f.recordAttackResolved(false, true, 7.5, Math.max(10.0, 7.5));
		assertEquals(0.75, f.efficiency(), 1e-9);
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * How long a cast with no projectile is given before nothing arriving is taken
 * as a miss.
 *
 * <p>Wiki (Hit delay): {@code MagicDelay = 1 + floor((1 + Distance) / 3)}, with
 * distance measured Chebyshev and, for these spells, from the player to the
 * NPC's south-west tile. Every earlier attempt used a constant here — three
 * ticks, then the weapon's speed — and the traces show why neither works.
 */
public class MagicHitDelayTest
{
	@Test
	public void theTwoCastsLoggedWithTheirDistances()
	{
		// Where the plus-one comes from. A cast queued at distance 2 was due on
		// 552 and its hitsplat arrived on 553; one at distance 6 was due on 454
		// and arrived on 455. Judged a tick early, both were called splashes,
		// and one of them had hit for 58.
		assertEquals(3, PvmPerformancePlugin.magicHitDelay(2));
		assertEquals(4, PvmPerformancePlugin.magicHitDelay(6));
	}

	@Test
	public void theDistantCastsFromTheEarlierTrace()
	{
		// Casts on 408, 413, 418 and 428 landed on 413, 418, 423 and 433: five.
		assertEquals(5, PvmPerformancePlugin.magicHitDelay(8));
		assertEquals(5, PvmPerformancePlugin.magicHitDelay(10));
	}

	@Test
	public void adjacentIsTheShortestDelay()
	{
		assertEquals(2, PvmPerformancePlugin.magicHitDelay(0));
		assertEquals(2, PvmPerformancePlugin.magicHitDelay(1));
	}

	@Test
	public void aCloseCastStillResolvesBeforeTheNextOne()
	{
		assertTrue(PvmPerformancePlugin.magicHitDelay(2) < 5);
	}

	@Test
	public void aNegativeDistanceCannotShortenIt()
	{
		assertEquals(2, PvmPerformancePlugin.magicHitDelay(-3));
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

// A special attack is not the attack the ordinary expected figures describe.
// Booking one with averageHit understates every special that raises accuracy
// and badly understates one whose hitsplats are capped, which is the case that
// started this: a Dawnbringer on Verzik's first phase expects three where it
// deals over a hundred.
public class SpecialAttackDamageTest
{
	private static final double EPSILON = 1e-9;

	/** The floor-aware average against brute force, which is what it replaces. */
	@Test
	public void cappedAverageWithAFloorMatchesBruteForce()
	{
		for (int max = 1; max <= 60; max++)
		{
			for (int min = 0; min <= max; min++)
			{
				for (int cap : new int[]{3, 10, 25, 1000})
				{
					double total = 0;
					for (int roll = min; roll <= max; roll++)
					{
						total += Math.min(roll, cap);
					}
					assertEquals(total / (max - min + 1),
						CombatCalc.cappedAverage(min, max, cap), EPSILON);
				}
			}
		}
	}

	/** With no floor it has to be the two-argument form exactly. */
	@Test
	public void aZeroFloorIsThePlainCappedAverage()
	{
		for (int max = 1; max <= 80; max++)
		{
			for (int cap : new int[]{3, 10, 47, Integer.MAX_VALUE})
			{
				assertEquals(CombatCalc.cappedAverage(max, cap),
					CombatCalc.cappedAverage(0, max, cap), EPSILON);
			}
		}
	}

	/**
	 * The Voidwaker's floor is worth as much as its guaranteed hit: Disrupt
	 * rolls 50% to 150% of the normal max, so it expects a WHOLE max hit rather
	 * than half of the raised one.
	 */
	@Test
	public void theVoidwakerExpectsAFullMaxHit()
	{
		final int normalMax = 40;
		final int[] maxima = SpecialAttack.VOIDWAKER.hitMaxima(normalMax);
		assertEquals(60, maxima[0]);
		final double expected = CombatCalc.specAverage(maxima, 1.0,
			SpecialAttack.VOIDWAKER.minFraction(), Integer.MAX_VALUE);
		// Between 20 and 60 averages 40, which is the normal max hit.
		assertEquals(normalMax, expected, 0.5);
		// Without the floor it would read three quarters of that, which is the
		// figure the ordinary average would have produced.
		assertNotEquals(expected,
			CombatCalc.specAverage(maxima, 1.0, 0.0, Integer.MAX_VALUE), 1.0);
	}

	/**
	 * A cap is per hitsplat, so it bites each hit of a multi-hit special
	 * separately rather than the activation's total.
	 */
	@Test
	public void aCapAppliesToEachHitsplatSeparately()
	{
		// Two 45s capped at 10 cannot expect more than 20 between them, however
		// large the maxima are.
		final double capped = CombatCalc.specAverage(new int[]{45, 45}, 1.0, 0.0, 10);
		assertTrue(capped <= 20.0);
		// And a cap is not a smaller max hit: rolling 0-45 and capping at 10
		// averages far nearer 10 than the 5 that halving a 10 max would give.
		assertTrue(capped > 15.0);
	}

	/**
	 * The claws' cascade of accuracy rolls is worth appreciably more than one
	 * roll for the whole activation, because a first-roll miss is usually
	 * rescued by the second.
	 */
	@Test
	public void theClawsCascadeBeatsASingleAccuracyRoll()
	{
		final int normalMax = 50;
		final double accuracy = 0.8;
		final double cascade = CombatCalc.clawsAverage(normalMax, accuracy, Integer.MAX_VALUE);
		// One roll for the lot, against the same 1, 1/2, 1/4, 1/4 shape.
		final double single = CombatCalc.specAverage(
			SpecialAttack.DRAGON_CLAWS.hitMaxima(normalMax), accuracy, 0.0, Integer.MAX_VALUE);
		assertTrue(cascade > single);
		// Worth about a fifth more at this accuracy, which is the figure the
		// cascade exists to capture.
		assertEquals(1.2, cascade / single, 0.05);
	}

	/** Every roll missing still deals something, so the floor is never zero. */
	@Test
	public void theClawsDealOneOnAverageWhenEveryRollMisses()
	{
		assertEquals(1.0, CombatCalc.clawsAverage(50, 0.0, Integer.MAX_VALUE), EPSILON);
	}

	/** A guaranteed hit spends none of its expectation on missing. */
	@Test
	public void theClawsAtFullAccuracyAreTheFirstOutcomeAlone()
	{
		final int normalMax = 48;
		// 24 + 12 + 6 + 6, the halves of the shape rounded as the table gives them.
		assertEquals(48.0, CombatCalc.clawsAverage(normalMax, 1.0, Integer.MAX_VALUE), EPSILON);
	}

	/**
	 * Pulsate is flat, and the one hit Verzik's first phase does not cap. The
	 * cap is what makes this worth a test: the ordinary figure for a magic
	 * attack there is three.
	 */
	@Test
	public void theDawnbringerExpectsItsOwnFlatRollAndIgnoresTheCap()
	{
		final SpecialAttack pulsate = SpecialAttack.DAWNBRINGER;
		assertTrue(pulsate.alwaysHits());
		assertTrue(pulsate.ignoresDamageCap());
		assertTrue(pulsate.hasFixedDamage());
		// 75 to 150 averages 112.5.
		assertEquals(112.5, CombatCalc.cappedAverage(75, 150, Integer.MAX_VALUE), 0.5);
		// The same roll held to Verzik's magic cap would read three, which is
		// what the plugin used to book for it.
		assertEquals(3.0, CombatCalc.cappedAverage(75, 150, 3), EPSILON);
	}

	/**
	 * The table's own invariants. A missing accuracy multiplier reads as 0 and
	 * would silently zero the special's expected damage, which a green build
	 * would not catch.
	 */
	@Test
	public void everySpecialCarriesAnAccuracyMultiplier()
	{
		for (SpecialAttack spec : SpecialAttack.values())
		{
			assertTrue(spec.name(), spec.getAttackRollMultiplier() > 0);
			assertTrue(spec.name(), spec.hits() >= 1);
			assertTrue(spec.name(), spec.minFraction() >= 0 && spec.minFraction() < 1);
		}
	}

	/**
	 * A special with no damage multipliers of its own is one hit at the max the
	 * caller worked out, which is how the fang, the bludgeon, the volatile staff
	 * and the Dawnbringer reach the average.
	 */
	@Test
	public void aSpecialWithoutMultipliersIsOneHitAtTheGivenMax()
	{
		for (SpecialAttack spec : new SpecialAttack[]{SpecialAttack.OSMUMTENS_FANG,
			SpecialAttack.ABYSSAL_BLUDGEON, SpecialAttack.VOLATILE_STAFF, SpecialAttack.DAWNBRINGER})
		{
			assertTrue(spec.name(), !spec.hasDamageMultipliers());
			assertEquals(spec.name(), 1, spec.hitMaxima(37).length);
			assertEquals(spec.name(), 37, spec.hitMaxima(37)[0]);
		}
	}

	/**
	 * The godswords double the attack ROLL, not the hit chance. Doubling the
	 * chance would put them over 100% against anything already hit two thirds
	 * of the time.
	 */
	@Test
	public void aDoubledAttackRollIsNotADoubledHitChance()
	{
		assertEquals(2.0, SpecialAttack.ARMADYL_GODSWORD.getAttackRollMultiplier(), EPSILON);
		final int roll = CombatCalc.attackRoll(100, 100, 1.0);
		assertEquals(2 * roll, SpecialAttack.ARMADYL_GODSWORD.scaleAttackRoll(roll));
	}

	/**
	 * The roll is scaled with integer arithmetic against the FINISHED roll, not
	 * folded in with the gear multiplier as a double. The game works in integers,
	 * and a double multiply can land a point either side after truncation - the
	 * same trap as fangMaxHit.
	 */
	@Test
	public void theAttackRollIsScaledAsAnExactRational()
	{
		final SpecialAttack dagger = SpecialAttack.DRAGON_DAGGER;
		assertEquals(1.15, dagger.getAttackRollMultiplier(), EPSILON);
		// 23/20 exactly, against every roll rather than at a few sample points.
		for (int roll = 0; roll <= 40000; roll += 7)
		{
			assertEquals((int) ((long) roll * 23 / 20), dagger.scaleAttackRoll(roll));
		}
		// A special that leaves the roll alone must return it untouched.
		for (int roll = 0; roll <= 40000; roll += 997)
		{
			assertEquals(roll, SpecialAttack.DRAGON_CLAWS.scaleAttackRoll(roll));
		}
	}

	/** The scaling must not overflow on a roll far larger than any real one. */
	@Test
	public void theRationalScalingDoesNotOverflow()
	{
		final int huge = Integer.MAX_VALUE / 2;
		assertEquals((int) ((long) huge * 143 / 100),
			SpecialAttack.MAGIC_SHORTBOW.scaleAttackRoll(huge));
		assertTrue(SpecialAttack.ARMADYL_GODSWORD.scaleAttackRoll(huge) > 0);
	}

	/**
	 * Burning claws were missing from the table entirely, so a spec showed no
	 * spec max and booked the ORDINARY expected hit. Their gameval name is
	 * BONE_CLAWS, which is why matching on the id rather than the name matters.
	 */
	@Test
	public void burningClawsAreInTheTableAndReachTheirWikiMax()
	{
		final SpecialAttack burning = SpecialAttack.BURNING_CLAWS;
		assertEquals(3, burning.hits());
		assertTrue(burning.cascadingAccuracy());
		// The first outcome's total reaches 175% of the max hit, split 25-25-50 -
		// but each hitsplat is floored on its own, so what LANDS is a point under
		// the total rolled. The wiki says so outright: a total roll of 29 "becomes
		// 7-7-14, a total of 28 actual damage, despite originally rolling for 29".
		assertEquals(69, burning.maxTotal(40));
		assertEquals(70, (int) (40 * 1.75));
		final int[] maxima = burning.hitMaxima(40);
		assertEquals(3, maxima.length);
		assertEquals(maxima[0], maxima[1]);
		assertTrue(maxima[2] > maxima[0]);
	}

	/**
	 * The wiki's own worked example, which also pins the flooring: "for a normal
	 * maximum hit of 39, the minimum and maximum hits for the first accuracy
	 * roll case are calculated as floor(0.75 * 39) and floor(1.75 * 39),
	 * resulting in a damage range of 29-68."
	 */
	@Test
	public void burningClawsMatchTheWikiWorkedExample()
	{
		assertEquals(29, (int) (39 * 0.75));
		assertEquals(68, (int) (39 * 1.75));
	}

	/**
	 * At full accuracy only the first outcome is reachable, and its total
	 * averages 125% of the max hit - the midpoint of 75% to 175%.
	 */
	@Test
	public void burningClawsAtFullAccuracyAverageTheFirstOutcome()
	{
		final int normalMax = 40;
		final double expected = CombatCalc.burningClawsAverage(normalMax, 1.0, Integer.MAX_VALUE);
		// Within a point of 1.25x, the rest being the per-hitsplat flooring.
		assertEquals(1.25 * normalMax, expected, 1.5);
	}

	/** Three misses still deal 0, 1 or 2 at 20/40/40, which averages 1.2. */
	@Test
	public void burningClawsDealTwelveTenthsWhenEveryRollMisses()
	{
		assertEquals(1.2, CombatCalc.burningClawsAverage(40, 0.0, Integer.MAX_VALUE), 1e-9);
	}

	/**
	 * The cascade is worth more than a single roll here too, and each later
	 * outcome is worth less than the one before - which is what says the rolls
	 * are being weighted by having got that far rather than treated alike.
	 */
	@Test
	public void burningClawsFallOffWithEachMissedRoll()
	{
		final int normalMax = 40;
		double previous = Double.MAX_VALUE;
		for (double accuracy : new double[]{1.0, 0.75, 0.5, 0.25})
		{
			final double value = CombatCalc.burningClawsAverage(normalMax, accuracy, Integer.MAX_VALUE);
			assertTrue(value < previous);
			previous = value;
		}
		// Never worse than the all-miss floor.
		assertTrue(CombatCalc.burningClawsAverage(normalMax, 0.01, Integer.MAX_VALUE) > 1.2);
	}

	/** A cap bites burning claws like any other special: it is not exempt. */
	@Test
	public void burningClawsAreCappedLikeAnythingElse()
	{
		assertTrue(CombatCalc.burningClawsAverage(60, 1.0, 10) <= 30.0);
		assertFalse(SpecialAttack.BURNING_CLAWS.ignoresDamageCap());
	}
}

package com.pvmperformance;

import java.util.HashSet;
import java.util.Set;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * A hitpoints experience drop lands on the tick the attack goes out, but only an
 * attack booked from its animation knows that tick exactly. The other two work
 * back from a lag, and both lags were seen a tick out in one log: a cast booked
 * from its hitsplat worked back to 72 for an attack thrown on 71, and a
 * projectile at a flat two ticks worked back to 129 for a drop on 128.
 */
public class DamageDealtWindowTest
{
	private static boolean dealt(Set<Integer> drops, int attackTick)
	{
		return drops.contains(attackTick)
			|| drops.contains(attackTick - 1)
			|| drops.contains(attackTick + 1);
	}

	private static Set<Integer> drops(int... ticks)
	{
		final Set<Integer> set = new HashSet<>();
		for (int tick : ticks)
		{
			set.add(tick);
		}
		return set;
	}

	@Test
	public void anExactTickIsTheOrdinaryCase()
	{
		assertTrue(dealt(drops(56, 61, 66, 71), 61));
	}

	@Test
	public void aCastBookedFromItsHitsplatLandsATickLate()
	{
		// Thrown on 71, worked back to 72 from an estimated hit delay.
		assertTrue(dealt(drops(71), 72));
	}

	@Test
	public void aProjectileLandsATickEarly()
	{
		// Drop on 128, worked back to 129 from the flat projectile lag.
		assertTrue(dealt(drops(128), 129));
	}

	@Test
	public void anAttackThatDealtNothingIsStillAMiss()
	{
		// The window must not turn every attack into a hit: casts every five
		// ticks, one of them splashing, and the splash has to survive it.
		assertFalse(dealt(drops(56, 61, 66), 71));
	}

	@Test
	public void theWindowCannotReachTheNextAttacksDrop()
	{
		// Nothing swings faster than two ticks, so a neighbour's drop is always
		// at least two away.
		assertFalse(dealt(drops(60), 58));
	}
}

