package com.pvmperformance;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

// The special attack energy varp does not fall on the tick the attack goes out,
// so matching the two by equality throws the special's expected damage away and
// books the ordinary one instead. This is the arithmetic that decides which
// attack an activation belongs to.
public class SpecialBookingWindowTest
{
	/**
	 * The case that was wrong in game, lifted from the trace: a burning claws
	 * special dropped the energy on tick 45 and its hitsplat landed on 46, so the
	 * equality check read false and booked 4.49 where the special expected 16.14.
	 */
	@Test
	public void theTracedBurningClawsSpecialIsBooked()
	{
		assertTrue(PvmPerformancePlugin.specialWentOutFor(46, 45));
	}

	/** A special whose attack lands on the same tick still counts. */
	@Test
	public void anAttackOnTheEnergyTickIsBooked()
	{
		assertTrue(PvmPerformancePlugin.specialWentOutFor(45, 45));
	}

	/**
	 * The window has to stay at one tick. The fastest weapon here attacks every
	 * two, so accepting two would let the NEXT ordinary attack claim the special
	 * as well - the failure this guards is over-attribution, not under.
	 */
	@Test
	public void theNextAttackOfAFastWeaponIsNotClaimed()
	{
		// Blowpipe on rapid: special on 45, its attack on 46, the next on 48.
		assertTrue(PvmPerformancePlugin.specialWentOutFor(46, 45));
		assertFalse(PvmPerformancePlugin.specialWentOutFor(47, 45));
		assertFalse(PvmPerformancePlugin.specialWentOutFor(48, 45));
	}

	/** An attack thrown before the energy fell cannot be that special's. */
	@Test
	public void anAttackBeforeTheEnergyFellIsNotBooked()
	{
		assertFalse(PvmPerformancePlugin.specialWentOutFor(44, 45));
		assertFalse(PvmPerformancePlugin.specialWentOutFor(0, 45));
	}

	/**
	 * No special has fired yet. The sentinel must not be subtracted from, which
	 * would overflow and read as an enormous gap either way round.
	 */
	@Test
	public void noSpecialYetIsNeverBooked()
	{
		assertFalse(PvmPerformancePlugin.specialWentOutFor(0, Integer.MIN_VALUE));
		assertFalse(PvmPerformancePlugin.specialWentOutFor(46, Integer.MIN_VALUE));
		assertFalse(PvmPerformancePlugin.specialWentOutFor(Integer.MAX_VALUE, Integer.MIN_VALUE));
	}

	/** A long trip must not start booking specials again as the tick count grows. */
	@Test
	public void anOldSpecialIsNotClaimedByALaterAttack()
	{
		for (int later = 47; later < 5000; later += 7)
		{
			assertFalse("tick " + later, PvmPerformancePlugin.specialWentOutFor(later, 45));
		}
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;

/**
 * The Chambers' guardians, which only a pickaxe hurts and which a pickaxe hurts
 * by a factor of {@code (50 + Mining level + pickaxe's level req) / 150}, from
 * Mod Ash. The table below is the level requirement half of it: transcription
 * rather than arithmetic, and wrong by one is a percent of damage that nobody
 * would ever notice in game.
 */
public class GuardianDamageTest
{
	private static double multiplier(int miningLevel, String pickaxe)
	{
		return (50.0 + miningLevel + CombatCalc.pickaxeLevelRequirement(pickaxe)) / 150.0;
	}

	@Test
	public void everyGuardianIdIsClaimed()
	{
		// All four on purpose. The gamevals read the pair as left and right with two dead forms; the wiki's calculator
		// reads the same four as normal and challenge mode. Claiming the block costs nothing on a corpse and is the only
		// way the multiplier cannot go missing in whichever mode the other reading is right about.
		assertTrue(EncounterGroup.isGuardian(NpcID.RAIDS_STONEGUARDIANS_LEFT));
		assertTrue(EncounterGroup.isGuardian(NpcID.RAIDS_STONEGUARDIANS_RIGHT));
		assertTrue(EncounterGroup.isGuardian(NpcID.RAIDS_STONEGUARDIANS_LEFT_DEAD));
		assertTrue(EncounterGroup.isGuardian(NpcID.RAIDS_STONEGUARDIANS_RIGHT_DEAD));
		// And nothing else in the room.
		assertFalse(EncounterGroup.isGuardian(NpcIds.GOBLIN));
		assertFalse(EncounterGroup.isGuardian(NpcID.RAIDS_TEKTON_FIGHTING_STANDARD));
	}

	@Test
	public void thePickaxeTableIsTheMiningRequirement()
	{
		assertEquals(1, CombatCalc.pickaxeLevelRequirement("Bronze pickaxe"));
		assertEquals(1, CombatCalc.pickaxeLevelRequirement("Iron pickaxe"));
		assertEquals(6, CombatCalc.pickaxeLevelRequirement("Steel pickaxe"));
		assertEquals(11, CombatCalc.pickaxeLevelRequirement("Black pickaxe"));
		assertEquals(21, CombatCalc.pickaxeLevelRequirement("Mithril pickaxe"));
		assertEquals(31, CombatCalc.pickaxeLevelRequirement("Adamant pickaxe"));
		assertEquals(41, CombatCalc.pickaxeLevelRequirement("Rune pickaxe"));
		assertEquals(41, CombatCalc.pickaxeLevelRequirement("Gilded pickaxe"));
	}

	@Test
	public void crystalCountsAsADragonPickaxeAndNotAsItsOwnRequirement()
	{
		// Mod Ash, 2019: the crystal pickaxe uses the dragon's 61 rather than its own 71. Its place at the top of the
		// wiki's list is its melee stats, not this.
		assertEquals(61, CombatCalc.pickaxeLevelRequirement("Crystal pickaxe"));
		assertEquals(61, CombatCalc.pickaxeLevelRequirement("Dragon pickaxe"));
		assertEquals(61, CombatCalc.pickaxeLevelRequirement("Dragon pickaxe (or)"));
		assertEquals(61, CombatCalc.pickaxeLevelRequirement("Infernal pickaxe"));
		assertEquals(61, CombatCalc.pickaxeLevelRequirement("3rd age pickaxe"));
		// An unknown or absent name takes the same default: the variants outnumber the exceptions.
		assertEquals(61, CombatCalc.pickaxeLevelRequirement(null));
	}

	@Test
	public void aScytheHitsByTheTargetsSizeAndTheSizeComesFromTheGame()
	{
		// The rule itself. What changed is where the size comes from - the client's own composition rather than the wiki
		// data, which is silent for every id it does not list and records the Chambers guardian as size 0.
		assertEquals(1, CombatCalc.scytheHits(0));
		assertEquals(1, CombatCalc.scytheHits(1));
		assertEquals(2, CombatCalc.scytheHits(2));
		assertEquals(3, CombatCalc.scytheHits(3));
		// Olm's hands are five tiles across and take all three hits. They were reading one, having no entry to ask.
		assertEquals(3, CombatCalc.scytheHits(5));
		assertEquals(3, CombatCalc.scytheHits(7));
	}

	@Test
	public void aBetterPickaxeAndMoreMiningAreBothWorthDamage()
	{
		// 99 Mining with a dragon pickaxe: (50 + 99 + 61) / 150.
		assertEquals(1.4, multiplier(99, "Dragon pickaxe"), 0.0001);
		// The same player with a rune pickaxe gives up a little over nine percent of it.
		assertEquals(1.2667, multiplier(99, "Rune pickaxe"), 0.0001);
		// And a bronze one is exactly no multiplier at all, which is the arithmetic falling out right rather than a case.
		assertEquals(1.0, multiplier(99, "Bronze pickaxe"), 0.0001);
		assertTrue(multiplier(99, "Dragon pickaxe") > multiplier(70, "Dragon pickaxe"));
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

// A special that lands several hitsplats is one attack, not several.
public class MultiHitAttackTest
{
	private static Fight fight()
	{
		return new Fight("Goblin", NpcIds.GOBLIN, 1, 100, 0L, null, 0);
	}

	/** One attack made, four hitsplats: one attempt, one landed hit. */
	@Test
	public void aClawSpecialIsOneAttack()
	{
		final Fight f = fight();
		f.recordAttackMade(true);
		f.recordAttackResolved(true, true, 10, 10);
		f.recordDamageDealt(20, 0L, true);
		f.recordDamageDealt(10, 0L, false);
		f.recordDamageDealt(5, 0L, false);
		f.recordDamageDealt(5, 0L, false);

		assertEquals(1, f.getAttempts());
		assertEquals(1, f.getHits());
		assertEquals(40, f.getDamageDealt());
		assertEquals(1.0, f.accuracy(), 0.0001);
		// The average is per attack, so the whole special is one 40 damage hit.
		assertEquals(40.0, f.averageHit(), 0.0001);
	}

	/**
	 * A claw special that opens with a zero and then connects still landed. The
	 * first hitsplat to deal damage is the one that credits the hit, not simply
	 * the first hitsplat of the burst.
	 */
	@Test
	public void aSpecialThatOpensWithAZeroStillLands()
	{
		final Fight f = fight();
		f.recordAttackMade(true);
		f.recordAttackResolved(true, true, 10, 10);
		f.recordDamageDealt(0, 0L, false);
		f.recordDamageDealt(12, 0L, true);
		f.recordDamageDealt(6, 0L, false);

		assertEquals(1, f.getAttempts());
		assertEquals(1, f.getHits());
		assertEquals(18, f.getDamageDealt());
	}

	/** A special that misses entirely is an attempt with no hit. */
	@Test
	public void aSpecialThatMissesEntirelyIsStillOneAttempt()
	{
		final Fight f = fight();
		f.recordAttackMade(true);
		f.recordAttackResolved(true, true, 10, 10);
		f.recordDamageDealt(0, 0L, false);
		f.recordDamageDealt(0, 0L, false);

		assertEquals(1, f.getAttempts());
		assertEquals(0, f.getHits());
		assertEquals(0.0, f.accuracy(), 0.0001);
	}

	/** A splash is an attack that landed nothing, and must not double count. */
	@Test
	public void aSplashIsTheAttackAlreadyCounted()
	{
		final Fight f = fight();
		f.recordAttackMade(true);
		f.recordAttackResolved(true, true, 10, 10);
		f.recordSplash(0L);

		assertEquals(1, f.getAttempts());
		assertEquals(0, f.getHits());
	}

	/**
	 * The whole point of the change: attempts now equal attacks made, so the
	 * measured and expected sides share a denominator.
	 */
	@Test
	public void attemptsTrackAttacksMade()
	{
		final Fight f = fight();
		for (int attack = 0; attack < 5; attack++)
		{
			f.recordAttackMade(true);
		f.recordAttackResolved(true, true, 10, 10);
			f.recordDamageDealt(7, 0L, true);
			f.recordDamageDealt(3, 0L, false); // a second hitsplat every time
		}
		assertEquals(5, f.getAttacksMade());
		assertEquals(5, f.getAttempts());
		assertEquals(5, f.getHits());
	}
}

package com.pvmperformance;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

// The ruby bolt effect is a share of the target's CURRENT health, so the health
// bar it reads has to belong to the target being asked about. It is read off
// whoever the player is interacting with, which is not always the same NPC.
public class RubyBoltTargetTest
{
	private static final int GOBLIN = NpcIds.GOBLIN;
	private static final int OTHER = GOBLIN + 1;

	/** The ordinary case: the bar is the target's own. */
	@Test
	public void aBarOnTheTargetIsUsed()
	{
		assertTrue(CombatCalc.healthBarBelongsTo(GOBLIN, 42, GOBLIN, 42));
	}

	/**
	 * The bug this guards. Taking the bar unchecked scaled the max health of one
	 * NPC by the bar of another, which is not an imprecise figure but a
	 * meaningless one.
	 */
	@Test
	public void aBarOnADifferentNpcIsRefused()
	{
		assertFalse(CombatCalc.healthBarBelongsTo(OTHER, 42, GOBLIN, 42));
	}

	/**
	 * Two of the same NPC standing together: the id matches and the instance
	 * does not, which is the case the id alone cannot separate.
	 */
	@Test
	public void aBarOnAnotherOfTheSameNpcIsRefused()
	{
		assertFalse(CombatCalc.healthBarBelongsTo(GOBLIN, 7, GOBLIN, 42));
	}

	/**
	 * With no fight open there is no index to check against, and refusing the
	 * bar then would read every target at full health.
	 */
	@Test
	public void theIndexIsOnlyCheckedOnceThereIsOne()
	{
		assertTrue(CombatCalc.healthBarBelongsTo(GOBLIN, 7, GOBLIN, -1));
		assertFalse(CombatCalc.healthBarBelongsTo(OTHER, 7, GOBLIN, -1));
	}

	/** Blood forfeit is 20% of CURRENT health, capped at 100. */
	@Test
	public void rubyDamageIsAFifthOfCurrentHealthCapped()
	{
		assertEquals(20, EnchantedBolt.rubyDamage(100));
		assertEquals(2, EnchantedBolt.rubyDamage(14));
		// The cap bites above 500 current health, not above 500 max.
		assertEquals(100, EnchantedBolt.rubyDamage(600));
		assertEquals(100, EnchantedBolt.rubyDamage(500));
		assertEquals(99, EnchantedBolt.rubyDamage(499));
	}

	/**
	 * The Kandarin hard diary raises every enchanted bolt rate by a tenth of
	 * itself, and is always active - the wiki is explicit that the headgear need
	 * not be worn, which is why nothing checks for it.
	 */
	@Test
	public void theKandarinDiaryRaisesEveryRateByATenth()
	{
		for (EnchantedBolt bolt : EnchantedBolt.values())
		{
			assertEquals(bolt.name(), bolt.chance(false) * 1.1, bolt.chance(true), 1e-9);
			assertTrue(bolt.name(), bolt.chance(false) > 0 && bolt.chance(true) < 1);
		}
		// PvM rates, which are the only ones this plugin scores.
		assertEquals(0.06, EnchantedBolt.RUBY.chance(false), 1e-9);
	}
}

