	private static final Map<Integer, WeaponCategory> BY_VARBIT = new HashMap<>();
	private static final Map<String, WeaponCategory> BY_NAME = new HashMap<>();

	static
	{
		for (WeaponCategory category : values())
		{
			BY_VARBIT.put(category.varbitValue, category);
			BY_NAME.put(category.gameName.toLowerCase(), category);
		}
	}

	@Getter
	private final int varbitValue;

	/** What the combat tab calls this category. */
	@Getter
	private final String gameName;

	@Getter
	private final List<AttackStyle> attackStyles;

	private final AttackStyle[] styleByVarp = new AttackStyle[6];

	WeaponCategory(int varbitValue, String gameName, List<AttackStyle> attackStyles)
	{
		this.varbitValue = varbitValue;
		this.gameName = gameName;
		this.attackStyles = attackStyles;
		for (AttackStyle style : attackStyles)
		{
			styleByVarp[style.getVarpValue()] = style;
		}
	}

	/** The category for a COMBAT_WEAPON_CATEGORY varbit value, or null if unmapped. */
	static WeaponCategory forVarbit(int varbitValue)
	{
		return BY_VARBIT.get(varbitValue);
	}

	/**
	 * The category the combat tab names, or null. The preferred way in: the name
	 * comes from the game and cannot drift, whereas the varbit ids have already
	 * been renumbered once under this table - powered staff moved from 23 to 24,
	 * which made every trident resolve as a banner.
	 */
	static WeaponCategory forName(String gameName)
	{
		if (gameName == null)
		{
			return null;
		}
		// The tab shows it as "Category: Whip".
		final int colon = gameName.indexOf(':');
		final String trimmed = (colon < 0 ? gameName : gameName.substring(colon + 1)).trim();
		return BY_NAME.get(trimmed.toLowerCase());
	}

	/** The option selected by a COM_MODE varplayer value, or null if it isn't one of ours. */
	AttackStyle styleFor(int varpValue)
	{
		if (varpValue < 0 || varpValue >= styleByVarp.length)
		{
			return null;
		}
		return styleByVarp[varpValue];
	}
}

package com.pvmperformance;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.NpcID;

// How far an NPC's defence can be drained, for the few that limit it.
final class DefenceDrainCap
{
	/** The most defence a drain can remove. Absent means no limit. */
	private static final Map<Integer, Integer> CAPS = build();

	private DefenceDrainCap()
	{
	}

	/**
	 * The lowest defence draining can take this NPC to, given the defence it
	 * starts with - the raid-scaled figure where that applies, since a cap is a
	 * number of levels rather than a share of them.
	 */
	static int floor(int npcId, int baseDefence)
	{
		return baseDefence - maxDrain(npcId, baseDefence);
	}

	/** How many levels of defence can be taken off this NPC in total. */
	static int maxDrain(int npcId, int baseDefence)
	{
		final Integer cap = CAPS.get(npcId);
		return cap == null ? baseDefence : Math.min(cap, baseDefence);
	}

	/** Whether draining does nothing at all to this NPC. */
	static boolean isImmune(int npcId)
	{
		return Integer.valueOf(0).equals(CAPS.get(npcId));
	}

	private static Map<Integer, Integer> build()
	{
		final Map<Integer, Integer> caps = new HashMap<>();

		// Verzik Vitur, in every phase and every mode: her defence cannot be lowered at all. The transitions are left out,
		// being unattackable.
		for (int id : new int[]{
			NpcID.VERZIK_INITIAL, NpcID.VERZIK_PHASE1, NpcID.VERZIK_PHASE2, NpcID.VERZIK_PHASE3,
			NpcID.VERZIK_INITIAL_BASE, NpcID.VERZIK_INITIAL_QUICKSTART,
			NpcID.VERZIK_INITIAL_STORY, NpcID.VERZIK_PHASE1_STORY,
			NpcID.VERZIK_PHASE2_STORY, NpcID.VERZIK_PHASE3_STORY,
			NpcID.VERZIK_INITIAL_HARD, NpcID.VERZIK_PHASE1_HARD,
			NpcID.VERZIK_PHASE2_HARD, NpcID.VERZIK_PHASE3_HARD,
			NpcID.VERZIK_INITIAL_HARD_BASE, NpcID.VERZIK_INITIAL_HARD_QUICKSTART,
		})
		{
			caps.put(id, 0);
		}

		// Demonic Brutus. The gameval name is nothing like the wiki's, so these were matched by id against what the monster
		// data calls them.
		caps.put(NpcID.COWBOSS_HARDMODE, 0);
		caps.put(NpcID.COWBOSS_HARDMODE_GHOST, 0);

		// Doom of Mokhaiotl: 30 off a defence of 90. Its defence also resets on each floor of the delve, which is a matter
		// for whatever tracks the drain.
		caps.put(NpcID.DOM_BOSS, 30);
		caps.put(NpcID.DOM_BOSS_SHIELDED, 30);
		caps.put(NpcID.DOM_BOSS_BURROWED, 30);

		return Collections.unmodifiableMap(caps);
	}
}

package com.pvmperformance;

import lombok.Getter;

// The multipliers contributed by a gear effect; effects stack multiplicatively. Ported from the LlemonDuck dps-
// calculator (BSD-2), (c) Paul Norton, which carries one damage figure; the split into two is new here.
@Getter
class GearBonus
{
	static final GearBonus NONE = new GearBonus(1.0, 1.0, 1.0);

	private final double accuracy;
	private final double damage;
	private final double expectedDamage;

	private GearBonus(double accuracy, double damage, double expectedDamage)
	{
		this.accuracy = accuracy;
		this.damage = damage;
		this.expectedDamage = expectedDamage;
	}

	/** An effect that lands on every hit, so the max and the average agree. */
	static GearBonus of(double accuracy, double damage)
	{
		return new GearBonus(accuracy, damage, damage);
	}

	/** An effect that boosts the attack roll and the damage by the same factor. */
	static GearBonus symmetric(double bonus)
	{
		return of(bonus, bonus);
	}

	/**
	 * An effect whose best case and average differ: {@code maxDamage} is
	 * reachable but {@code expectedDamage} is what it averages out to.
	 */
	static GearBonus split(double accuracy, double maxDamage, double expectedDamage)
	{
		return new GearBonus(accuracy, maxDamage, expectedDamage);
	}

	GearBonus combine(GearBonus other)
	{
		if (other == NONE)
		{
			return this;
		}
		if (this == NONE)
		{
			return other;
		}
		return new GearBonus(
			accuracy * other.accuracy,
			damage * other.damage,
			expectedDamage * other.expectedDamage);
	}

	boolean isNone()
	{
		return accuracy == 1.0 && damage == 1.0 && expectedDamage == 1.0;
	}
}

package com.pvmperformance;

import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

/**
 * The raid the player is inside, if any. Read from the game's own varbits rather
 * than inferred from what is being fought, so entering is known before the first
 * NPC and leaving is known at once.
 */
enum RaidType
{
	CHAMBERS_OF_XERIC("Chambers of Xeric"),
	THEATRE_OF_BLOOD("Theatre of Blood"),
	TOMBS_OF_AMASCUT("Tombs of Amascut");

	private final String displayName;

	RaidType(String displayName)
	{
		this.displayName = displayName;
	}

	String getDisplayName()
	{
		return displayName;
	}

	/** The raid the player is in, or null outside one. */
	static RaidType current(Client client)
	{
		// None of these varbits is reliably cleared on leaving, so a fight in Prifddinas was filed under Theatre of Blood on
		// a leftover progress value. Requiring an instance is not the whole answer - a house is instanced too - but it keeps
		// the open world clean.
		if (!client.isInInstancedRegion())
		{
			return null;
		}
		if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1)
		{
			return CHAMBERS_OF_XERIC;
		}
		// The wave, not TOB_PROGRESS. That runs 0 to 5 and counts how far the player has ever got through the Theatre, not
		// whether they are in it now - it read non-zero for anyone who has been near the place, and filed every goblin ever
		// killed under Theatre of Blood.
		if (client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_VAL) > 0)
		{
			return THEATRE_OF_BLOOD;
		}
		// The party status, not the raid level: the level is never cleared on leaving, while the status is 1 inside and 0
		// everywhere else.
		if (client.getVarbitValue(VarbitID.TOA_CLIENT_PARTYSTATUS) > 0)
		{
			return TOMBS_OF_AMASCUT;
		}
		return null;
	}
}

