import java.util.ArrayList;
import java.util.List;
import lombok.Getter;

// One run of a raid: its rooms, in the order they were fought.
@Getter
class Raid
{
	private final RaidType type;
	private final String name;
	private final int id;
	private final long startMillis;
	private final List<Encounter> encounters = new ArrayList<>();
	private long endMillis;

	Raid(RaidType type, int id, long now)
	{
		this(type, type.getDisplayName(), id, now);
	}

	/** Rebuilt from a history file, which stores the raid's name and not its type. */
	Raid(String name, int id, long now)
	{
		this(null, name, id, now);
	}

	private Raid(RaidType type, String name, int id, long now)
	{
		this.type = type;
		this.name = name;
		this.id = id;
		this.startMillis = now;
	}

	void add(Encounter encounter)
	{
		encounters.add(encounter);
	}

	void end(long now)
	{
		endMillis = now;
	}

	int getDamageDealt()
	{
		int total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.getDamageDealt();
		}
		return total;
	}

	int getAttempts()
	{
		int total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.getAttempts();
		}
		return total;
	}

	int getTargets()
	{
		int total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.getTargets();
		}
		return total;
	}

	double accuracy()
	{
		final int targets = getTargets();
		return targets == 0 ? 0 : (double) getHits() / targets;
	}

	int getHits()
	{
		int total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.getHits();
		}
		return total;
	}

	double sumExpectedAverageHit()
	{
		double total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.sumExpectedAverageHit();
		}
		return total;
	}

	double sumExpectedAccuracy()
	{
		double total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.sumExpectedAccuracy();
		}
		return total;
	}

	int getAttacksMade()
	{
		int total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.getAttacksMade();
		}
		return total;
	}

	int getAttacksPrayed()
	{
		int total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.getAttacksPrayed();
		}
		return total;
	}

	int getAttacksSwitched()
	{
		int total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.getAttacksSwitched();
		}
		return total;
	}

	int getAttacksPotted()
	{
		int total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.getAttacksPotted();
		}
		return total;
	}

	double efficiency()
	{
		double actual = 0;
		double ideal = 0;
		for (Encounter encounter : encounters)
		{
			for (Fight fight : encounter.getFights())
			{
				if (fight.isScored())
				{
					actual += fight.getSumActualSetup();
					ideal += fight.getSumIdealSetup();
				}
			}
		}
		return ideal <= 0 ? -1 : actual / ideal;
	}

	int getTicksLost()
	{
		int total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.getTicksLost();
		}
		return total;
	}

	int getTicksLostEating()
	{
		int total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.getTicksLostEating();
		}
		return total;
	}

	int getCombatTicks()
	{
		int total = 0;
		for (Encounter encounter : encounters)
		{
			total += encounter.getCombatTicks();
		}
		return total;
	}

	double ticksLostShare()
	{
		final int ticks = getCombatTicks();
		return ticks <= 0 ? -1 : (double) getTicksLost() / ticks;
	}

	long durationMillis()
	{
		long last = startMillis;
		for (Encounter encounter : encounters)
		{
			last = Math.max(last, encounter.getStartMillis() + encounter.durationMillis());
		}
		return Math.max(0, (endMillis > 0 ? endMillis : last) - startMillis);
	}
}

package com.pvmperformance;

import lombok.Getter;

// Aggregated performance against one target, where a target is a room when its NPCs are grouped and a single NPC
// otherwise - so the Nylocas add up per colour and Kephri's room reads as Kephri, while a Vorkath is still a Vorkath.
@Getter
class NpcStats
{
	private final String name;
	// Rooms, not sub-fights: one Hueycoatl is a body then a head, and counting those separately read as "2 fights, 1 kill"
	// for one clean kill.
	private int fights;
	private int kills;
	private int maxHp = -1;
	private long totalDamageDealt;
	private long totalDamageTaken;
	private long totalDurationMillis;
	private int totalAttempts;
	private int totalHits;
	private int ticksLost;
	private int combatTicks;
	private double sumActualSetup;
	private double sumIdealSetup;

	NpcStats(String name)
	{
		this.name = name;
	}

	/**
	 * @param startsRoom whether this fight opens a new room rather than
	 *                   continuing the one before it
	 */
	void add(Fight fight, boolean startsRoom)
	{
		if (startsRoom)
		{
			fights++;
		}
		if (fight.isTargetDied())
		{
			kills++;
		}
		totalDamageTaken += fight.getDamageTaken();
		totalDurationMillis += fight.durationMillis();
		ticksLost += fight.getTicksLost();
		combatTicks += fight.getCombatTicks();
		if (!fight.isScored())
		{
			return;
		}
		maxHp = Math.max(maxHp, fight.getMaxHp());
		totalDamageDealt += fight.getDamageDealt();
		totalAttempts += fight.resolvedAttempts();
		totalHits += fight.getHits();
		sumActualSetup += fight.getSumActualSetup();
		sumIdealSetup += fight.getSumIdealSetup();
	}

	/**
	 * Damage the attacks were set up to deal against what they would have with
	 * the intended prayer and a full boost, or -1 if nothing was comparable.
	 */
	double efficiency()
	{
		return sumIdealSetup <= 0 ? -1 : sumActualSetup / sumIdealSetup;
	}

	/** Share of attackable ticks that went unused, or -1 if none were counted. */
	double ticksLostShare()
	{
		return combatTicks <= 0 ? -1 : (double) ticksLost / combatTicks;
	}

	double avgDps()
	{
		final double seconds = totalDurationMillis / 1000.0;
		return seconds < 0.6 ? 0 : totalDamageDealt / seconds;
	}

	/**
	 * Mean damage per attack, counting misses as zero and denominated on attacks
	 * that resolved: one nulled by the kill dealt nothing because there was
	 * nothing left to deal it to.
	 */
	double avgHit()
	{
		return totalAttempts == 0 ? 0 : (double) totalDamageDealt / totalAttempts;
	}

	double accuracy()
	{
		return totalAttempts == 0 ? 0 : (double) totalHits / totalAttempts;
	}
}

