/**
 * What the tracker saw, in two forms.
 *
 * <p>A rolling window of the last few thousand lines is kept ALWAYS, and the
 * side panel can write it out. That is the one that matters: every bug in this
 * plugin so far was reported as "I just saw something odd", and a log that has
 * to be switched on beforehand asks the player to predict which kill will go
 * wrong.
 *
 * <p>The config toggle is the second form. It streams every line to a file for
 * as long as it is on, for a session spent deliberately hunting something, and
 * it survives a crash where the window in memory does not.
 *
 * <p>Nothing here touches the disk on the client thread: a line is formatted
 * where it happens, queued, and written by the scheduler a couple of seconds
 * later.
 */
@Slf4j
@Singleton
class DebugLog
{
	private static final String DIR = "pvm-performance-tracker";
	private static final DateTimeFormatter STAMP = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");
	private static final long FLUSH_SECONDS = 2;
	/**
	 * A ceiling in case the writer stalls. Roughly twenty minutes of the busiest
	 * tick this logs, so reaching it means something is wrong with the writing
	 * rather than with the logging.
	 */
	private static final int MAX_PENDING = 50000;
	/**
	 * How much of the recent past is held in memory, ready to be written out
	 * when something looks wrong.
	 *
	 * <p>Counted in LINES rather than minutes on purpose. A busy tick writes
	 * sixteen lines and a quiet one writes none, so a window measured in time
	 * bounds nothing; measured in lines it bounds itself. Real logs run at
	 * around 0.7 lines a tick and 75 bytes a line, so this is a good twenty
	 * minutes of fighting and about 400KB at its very fullest.
	 */
	private static final int RECENT_LINES = 5000;

	private final Client client;
	private final ScheduledExecutorService executor;

	private final Queue<String> pending = new ConcurrentLinkedQueue<>();
	/**
	 * The rolling window, kept whether or not anything is being written to disk.
	 *
	 * <p>Gating this on the toggle was considered and rejected: it would only
	 * ever hold what happened after the toggle went on, which is the predict-
	 * the-bug problem the button exists to solve. What the toggle controls is
	 * the WRITING, not the watching. Guarded by its own lock rather than made
	 * concurrent, since it is touched once a tick and drained once a session.
	 */
	private final Deque<String> recent = new ArrayDeque<>(RECENT_LINES);
	private final AtomicInteger queued = new AtomicInteger();
	private final AtomicInteger dropped = new AtomicInteger();

	// Read on every logged line, so both are volatile rather than synchronized: the switch itself is rare.
	private volatile boolean on;
	private volatile Path file;
	private ScheduledFuture<?> flusher;

	@Inject
	DebugLog(Client client, ScheduledExecutorService executor)
	{
		this.client = client;
		this.executor = executor;
	}

	boolean isOn()
	{
		return on;
	}

	/** The file being written, or null while logging is off. */
	Path getFile()
	{
		return file;
	}

	synchronized void start()
	{
		if (on)
		{
			return;
		}
		file = new File(new File(RuneLite.RUNELITE_DIR, DIR),
			"pvm-debug-" + LocalDateTime.now().format(STAMP) + ".log").toPath();
		pending.clear();
		queued.set(0);
		dropped.set(0);
		on = true;
		flusher = executor.scheduleWithFixedDelay(this::flush, FLUSH_SECONDS, FLUSH_SECONDS, TimeUnit.SECONDS);
		log("debug logging to file on, plugin %s", version());
		log("send this file with a description of what you did and what you expected to see");
	}

	synchronized void stop()
	{
		if (!on)
		{
			return;
		}
		final int lost = dropped.get();
		if (lost > 0)
		{
			log("%d lines were dropped: the queue filled up", lost);
		}
		log("debug logging off");
		on = false;
		if (flusher != null)
		{
			flusher.cancel(false);
			flusher = null;
		}
		// The last few lines are still queued, so one more write after the switch goes off.
		executor.execute(this::flush);
	}

	/**
	 * One line. Always formatted, because the window is always watching - about
	 * one {@link String#format} per tick at the rate real logs run at, which is
	 * the price of being able to ask what just happened after it has happened.
	 */
	void log(String format, Object... args)
	{
		final String line;
		try
		{
			line = args.length == 0 ? format : String.format(format, args);
		}
		catch (Exception e)
		{
			// A bad format string must never take down the thing being logged.
			keep("[?] BAD LOG FORMAT: " + format);
			return;
		}
		keep("[" + tick() + "] " + line);
	}

	/** Into the window always, and onto the disk queue only while that is on. */
	private void keep(String line)
	{
		synchronized (recent)
		{
			if (recent.size() == RECENT_LINES)
			{
				recent.removeFirst();
			}
			recent.addLast(line);
		}
		if (!on)
		{
			return;
		}
		if (queued.get() >= MAX_PENDING)
		{
			dropped.incrementAndGet();
			return;
		}
		pending.add(line);
		queued.incrementAndGet();
	}

	/**
	 * Writes the window to its own file, newest session state first, and returns
	 * where it went - or null if there was nothing to write or it could not be
	 * written.
	 *
	 * <p>The header is the caller's: what was worn, which boost and prayer the
	 * player said they meant to bring, and how the plugin is configured. Nearly
	 * every figure questioned so far turned on one of those, and a list of
	 * numbers with no setup attached cannot answer for itself.
	 */
	Path saveRecent(List<String> header)
	{
		final List<String> lines;
		synchronized (recent)
		{
			if (recent.isEmpty())
			{
				return null;
			}
			lines = new ArrayList<>(recent);
		}
		final Path target = new File(new File(RuneLite.RUNELITE_DIR, DIR),
			"pvm-debug-recent-" + LocalDateTime.now().format(STAMP) + ".log").toPath();
		final StringBuilder buffer = new StringBuilder();
		buffer.append("=== PvM Performance, the last ").append(lines.size())
			.append(" lines before this was saved. Plugin ").append(version()).append(" ===")
			.append(System.lineSeparator());
		if (header != null)
		{
			for (String line : header)
			{
				buffer.append("  ").append(line).append(System.lineSeparator());
			}
		}
		buffer.append("=== log ===").append(System.lineSeparator());
		for (String line : lines)
		{
			buffer.append(line).append(System.lineSeparator());
		}
		try
		{
			Files.createDirectories(target.getParent());
			Files.write(target, buffer.toString().getBytes(StandardCharsets.UTF_8),
				StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
			return target;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("PvM Performance: could not write the recent debug log", e);
			return null;
		}
	}

	private int tick()
	{
		try
		{
			return client.getTickCount();
		}
		catch (Exception e)
		{
			return -1;
		}
	}

	private String version()
	{
		final Package pkg = getClass().getPackage();
		final String implementation = pkg == null ? null : pkg.getImplementationVersion();
		return implementation == null ? "dev" : implementation;
	}

	private void flush()
	{
		final Path target = file;
		if (target == null || pending.isEmpty())
		{
			return;
		}
		final StringBuilder buffer = new StringBuilder();
		String line;
		while ((line = pending.poll()) != null)
		{
			queued.decrementAndGet();
			buffer.append(line).append(System.lineSeparator());
		}
		if (buffer.length() == 0)
		{
			return;
		}
		try
		{
			Files.createDirectories(target.getParent());
			Files.write(target, buffer.toString().getBytes(StandardCharsets.UTF_8),
				StandardOpenOption.CREATE, StandardOpenOption.APPEND);
		}
		catch (IOException | RuntimeException e)
		{
			// Switched off rather than retried: a log that cannot be written is not worth failing a fight over, and the
			// warning says where to look. Anything unchecked is caught for the same reason and one more - a scheduled task
			// that throws is cancelled silently, so letting one escape would stop the writing without stopping the queueing.
			on = false;
			log.warn("PvM Performance: debug log could not be written, logging off", e);
		}
	}
}

package com.pvmperformance;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.plugins.specialcounter.SpecialCounterUpdate;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;

// How much defence has been drained off each NPC being fought.
@Slf4j
@Singleton
class DefenceDrain
{
	// A special lands on the tick it is thrown for melee, a few ticks later for thrown and fired ones. Past this it is
	// forgotten rather than credited to whatever is hit next.
	private static final int MEMORY_TICKS = 4;

	private static final Map<Integer, SpecialWeapon> BY_ITEM_ID = new HashMap<>();

	static
	{
		for (SpecialWeapon weapon : SpecialWeapon.values())
		{
			for (int id : weapon.getItemID())
			{
				BY_ITEM_ID.put(id, weapon);
			}
		}
	}

	private static final int MAX_SPEC_ENERGY = 1000;
	private static final int HIT_WINDOW_TICKS = 5;

	private final Client client;
	private final MonsterStatsProvider monsters;
	private final PartyHitpoints partyHitpoints;

	// npc index -> defence levels taken off it.
	private final Map<Integer, Integer> drained = new HashMap<>();

	// Seeded from the live value rather than left unknown, so the first special after a reset is measured against
	// something: at -1 it was swallowed.
	private int specEnergy = -1;
	private SpecialWeapon firedWeapon;
	private int firedTick = Integer.MIN_VALUE;

	@Inject
	DefenceDrain(Client client, MonsterStatsProvider monsters, PartyHitpoints partyHitpoints)
	{
		this.client = client;
		this.monsters = monsters;
		this.partyHitpoints = partyHitpoints;
	}

	/** Levels of defence already taken off this NPC. */
	int drainedFrom(int npcIndex)
	{
		final Integer levels = drained.get(npcIndex);
		return levels == null ? 0 : levels;
	}

	/**
	 * Notices the player's own special going out, from the energy falling. The
	 * party message carries only what other members did, so a solo player's own
	 * specials have to be seen here or not at all.
	 */
	void onEnergyChanged()
	{
		final int energy = client.getVarpValue(VarPlayerID.SA_ENERGY);
		final int previous = specEnergy;
		specEnergy = energy;
		if (previous < 0)
		{
			// First reading since a reset. A full bar cannot have just been spent, so anything short of it is a special that
			// already went out.
			if (energy >= MAX_SPEC_ENERGY)
			{
				return;
			}
		}
		else if (energy >= previous)
		{
			return;
		}
		final SpecialWeapon weapon = equippedSpecialWeapon();
		if (weapon != null)
		{
			firedWeapon = weapon;
			firedTick = client.getTickCount();
		}
	}

	/**
	 * Applies the special's drain when its hit lands. The hit decides the amount
	 * for both kinds - a percentage of what remains, or the damage dealt - so
	 * nothing can be worked out until it arrives.
	 */
	void onMyHitsplat(NPC npc, int amount)
	{
		if (firedWeapon == null || client.getTickCount() - firedTick > HIT_WINDOW_TICKS)
		{
			firedWeapon = null;
			return;
		}
		final SpecialWeapon weapon = firedWeapon;
		firedWeapon = null;
		apply(npc, weapon, amount);
	}

	/** A drain landed by someone else in the party. */
	void onSpecialCounterUpdate(SpecialCounterUpdate event, NPC npc)
	{
		if (npc != null && npc.getIndex() == event.getNpcIndex())
		{
			apply(npc, event.getWeapon(), event.getHit());
		}
	}

	// Books a drain against the NPC, stopping at whatever floor it has.
	private void apply(NPC npc, SpecialWeapon weapon, int hit)
	{
		final MonsterStatsProvider.MonsterStats stats = monsters.get(npc.getId());
		if (stats == null)
		{
			return;
		}
		// The scaled figure, since that is the defence the drain is a share of.
		final int base = RaidScaling.defence(client, stats.getDefenceLevel(), stats.getName(), partyHitpoints.highest());
		final int already = drainedFrom(npc.getIndex());
		final int remaining = base - already;
		if (remaining <= 0)
		{
			return;
		}

		int taken;
		if (weapon.isDamage())
		{
			taken = weapon.computeHit(hit, npc);
		}
		else
		{
			final float keep = weapon.computeDrainPercent(hit, npc);
			if (keep <= 0)
			{
				return;
			}
			taken = remaining - (int) (remaining * keep);
		}
		if (taken <= 0)
		{
			return;
		}

		final int ceiling = DefenceDrainCap.maxDrain(npc.getId(), base);
		final int total = Math.min(ceiling, Math.min(base, already + taken));
		if (total != already)
		{
			drained.put(npc.getIndex(), total);
			log.debug("PvM Performance: {} drained to {} of {} defence by {}",
				npc.getName(), base - total, base, weapon.getName());
		}
	}

	/** The drain dies with the NPC, as its stats do. */
	void forget(int npcIndex)
	{
		drained.remove(npcIndex);
	}

	void clear()
	{
		drained.clear();
		firedWeapon = null;
		specEnergy = -1;
	}

	private SpecialWeapon equippedSpecialWeapon()
	{
		final int weaponId = equippedWeaponId();
		if (weaponId <= 0)
		{
			return null;
		}
		return BY_ITEM_ID.get(weaponId);
	}

	private int equippedWeaponId()
	{
		final ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return -1;
		}
		final Item item = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		return item == null ? -1 : item.getId();
	}
}

package com.pvmperformance;

import java.util.Arrays;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

// A set of worn items, by slot.
final class Loadout
{
	private static final int SLOTS = EquipmentInventorySlot.AMMO.getSlotIdx() + 1;

	private final ItemManager itemManager;
	private final int[] ids;
	private final String[] names = new String[SLOTS];

	private Loadout(ItemManager itemManager, int[] ids)
	{
		this.itemManager = itemManager;
		this.ids = ids;
	}

	/** What the player is wearing, or an empty loadout if that cannot be read. */
	static Loadout worn(ItemManager itemManager, ItemContainer equipment)
	{
		final int[] ids = new int[SLOTS];
		Arrays.fill(ids, -1);
		if (equipment != null)
		{
			for (int slot = 0; slot < SLOTS; slot++)
			{
				final Item item = equipment.getItem(slot);
				ids[slot] = item == null ? -1 : item.getId();
			}
		}
		return new Loadout(itemManager, ids);
	}

	/**
	 * This loadout with one slot swapped, leaving this one untouched: a search
	 * walks candidates by making these, so it must not disturb what it came
	 * from.
	 */
	Loadout with(EquipmentInventorySlot slot, int itemId)
	{
		final int idx = slot.getSlotIdx();
		if (idx < 0 || idx >= SLOTS || ids[idx] == itemId)
		{
			return this;
		}
		final int[] swapped = ids.clone();
		swapped[idx] = itemId;
		return new Loadout(itemManager, swapped);
	}

	/**
	 * Whether two loadouts hold the same item in every slot. Compared by
	 * contents, not identity: the worn loadout is rebuilt every tick, so two
	 * objects describing the same gear are the normal case.
	 */
	boolean sameItems(Loadout other)
	{
		return other != null && Arrays.equals(ids, other.ids);
	}

	int id(EquipmentInventorySlot slot)
	{
		final int idx = slot.getSlotIdx();
		return idx < 0 || idx >= SLOTS ? -1 : ids[idx];
	}

	String name(EquipmentInventorySlot slot)
	{
		final int idx = slot.getSlotIdx();
		if (idx < 0 || idx >= SLOTS)
		{
			return null;
		}
		if (names[idx] == null)
		{
			final int id = ids[idx];
			names[idx] = id < 0 ? "" : itemManager.getItemComposition(id).getName();
		}
		return names[idx].isEmpty() ? null : names[idx];
	}
}

