package com.pvmperformance;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

class PvmPerformanceOverlay extends OverlayPanel
{
	/**
	 * The panel is only as wide as it needs to be. A single fight's lines fit
	 * the standard width; a whole trip's do not - "Damage 83,955 / 100,811"
	 * wrapped onto a second line and the box became a wall of half sentences.
	 * Measured every frame from the text actually about to be drawn, since what
	 * is on it changes with the mode, the loadout and the size of the numbers.
	 */
	private static final int MIN_WIDTH = 129;
	/** Past this a long name is better wrapped than allowed to cross the screen. */
	private static final int MAX_WIDTH = 400;
	/** The panel's own border, plus the gap that keeps the two columns apart. */
	private static final int PADDING = 14;

	private final PvmPerformancePlugin plugin;
	private final PvmPerformanceConfig config;

	// Set at the top of each render and used by line(); the overlay is drawn on one thread.
	private FontMetrics metrics;
	private int contentWidth;

	@Inject
	PvmPerformanceOverlay(PvmPerformancePlugin plugin, PvmPerformanceConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		metrics = graphics.getFontMetrics();
		contentWidth = 0;

		final Fight fight = plugin.getDisplayFight();
		if (fight == null)
		{
			return null;
		}
		// A finished fight is left up so the kill can be read, but it was left up FOREVER: the last fight of a trip sat on
		// screen until the next one, which outside a boss trip is the rest of the session. It now goes when the fight
		// timeout says the fighting is over, which is the same clock that ended the fight itself.
		if (fight.isEnded()
			&& System.currentTimeMillis() - fight.getEndMillis() > config.fightTimeoutTicks() * 600L)
		{
			return null;
		}
		if (config.overlayBossesOnly() && !plugin.isBoss(fight))
		{
			return null;
		}

		// Expected-only asks for the loadout's figures and nothing else. Otherwise it is the whole trip, the raid so far, or
		// the room being fought - the room by default, since a single fight would blink between a room's adds.
		final boolean expectedOnly = config.overlayExpectedOnly();
		final SessionTotals session = expectedOnly || !config.overlaySessionTotals()
			? null : plugin.getSession();
		final Raid raid = expectedOnly || session != null || config.raidScope() != RaidScope.RAID
			? null : plugin.getCurrentRaid();
		final Encounter room = session != null || raid != null ? null : plugin.getDisplayEncounter();
		if (!expectedOnly && session == null && raid == null && room == null)
		{
			return null;
		}

		final String heading = title(session, raid, room, fight);
		contentWidth = Math.max(contentWidth, metrics.stringWidth(heading));
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(heading)
			.build());

		final SpecialAttack spec = plugin.getSpecialAttack();
		final int specMaxHit = plugin.getExpectedSpecMaxHit();
		final boolean hasSpec = spec != null && specMaxHit > 0;

		final int maxHit = plugin.getExpectedMaxHit();
		if (maxHit > 0)
		{
			line(hasSpec ? "Max hit (Spec)" : "Max hit",
				hasSpec ? String.format("%d (%d)", maxHit, specMaxHit) : String.valueOf(maxHit));
		}

		// Top half: what the loadout does against this target. These hold still through a fight, so they read as stats rather
		// than as a running score.
		final double expAcc = plugin.getExpectedAccuracy();
		final double specAcc = plugin.getExpectedSpecAccuracy();
		if (expAcc >= 0)
		{
			line(hasSpec ? "Accuracy (Spec)" : "Accuracy",
				hasSpec && specAcc >= 0 ? String.format("%.1f%% (%.1f%%)", expAcc * 100, specAcc * 100) : String.format("%.1f%%", expAcc * 100));
		}

		final double expAvgHit = plugin.getExpectedAverageHit();
		final double specAvgHit = plugin.getExpectedSpecAverageHit();
		if (expAvgHit >= 0)
		{
			line(hasSpec ? "Avg hit (Spec)" : "Avg hit",
				hasSpec && specAvgHit >= 0 ? String.format("%.2f (%.2f)", expAvgHit, specAvgHit) : String.format("%.2f", expAvgHit));
		}

		// Under Avg hit because it answers the question a bigger average hit cannot: which of two setups is actually better
		// when they swing at different speeds. Off the weapon's own cooldown rather than any clock, so it holds still through
		// a fight like the rest of this half.
		final double expDps = plugin.getExpectedDps();
		if (expDps >= 0)
		{
			line("DPS", String.format("%.2f", expDps));
		}

		if (expectedOnly)
		{
			return super.render(graphics);
		}

		// Bottom half: what happened, against what the model expected. The expected side is a running total of each attack's
		// own figure, so swapping weapons mid-fight adds each weapon's share.
		line("", "");

		final int damage = session != null ? session.getDamageDealt()
			: raid != null ? raid.getDamageDealt() : room.getDamageDealt();
		final double expDamage = session != null ? session.getSumExpectedAverageHit()
			: raid != null ? raid.sumExpectedAverageHit() : room.sumExpectedAverageHit();
		line("Damage",
			expDamage > 0 ? String.format("%s / %.0f", QuantityFormatter.formatNumber(damage), expDamage) : QuantityFormatter.formatNumber(damage));

		final int hits = session != null ? session.getHits()
			: raid != null ? raid.getHits() : room.getHits();
		// Measured hits against what was expected, then the accuracy those two make. The top half carries the accuracy the
		// LOADOUT should get; this is the one that happened.
		final double realAccuracy = session != null ? session.accuracy()
			: raid != null ? raid.accuracy() : room.accuracy();
		// Landed against what was EXPECTED to land, which is the comparison this plugin is for. How many were thrown is
		// already on screen under Efficiency, where prayed, potted and switches all divide by it, so spending this line on
		// it would only repeat that. The percentage is the real one - landed over thrown - so the two figures beside it
		// and the number below it always agree.
		//
		// With an AoE weapon both halves are per npc reached: five adds caught by one throw are five chances, and the
		// expected side is the sum of their five accuracies.
		final double expHits = session != null ? session.getSumExpectedAccuracy()
			: raid != null ? raid.sumExpectedAccuracy() : room.sumExpectedAccuracy();
		line("Hits", expHits > 0
			? String.format("%d / %.1f (%.0f%%)", hits, expHits, realAccuracy * 100)
			: String.valueOf(hits));

		// How well the attacks were set up, with the parts shown only when one of them slipped, a clean fight needs no
		// breakdown.
		final double efficiency = session != null ? session.efficiency()
			: raid != null ? raid.efficiency() : room.efficiency();
		if (efficiency >= 0)
		{
			line("Efficiency", String.format("%.0f%%", efficiency * 100));

			final int made = session != null ? session.getAttacksMade()
				: raid != null ? raid.getAttacksMade() : room.getAttacksMade();
			final int prayed = session != null ? session.getAttacksPrayed()
				: raid != null ? raid.getAttacksPrayed() : room.getAttacksPrayed();
			final int potted = session != null ? session.getAttacksPotted()
				: raid != null ? raid.getAttacksPotted() : room.getAttacksPotted();
			// Always shown, both of them. Hiding a counter that reads full makes it impossible to tell a perfect run from one
			// that is not counting.
			line("  prayed", prayed + "/" + made);
			line("  potted", potted + "/" + made);
			final int switched = session != null ? session.getAttacksSwitched()
				: raid != null ? raid.getAttacksSwitched() : room.getAttacksSwitched();
			// The gap to made is the number of attacks that missed at least one switch, read the same way as the two lines above
			// it.
			line("  switches", switched + "/" + made);
		}

		final double lostShare = session != null ? session.ticksLostShare()
			: raid != null ? raid.ticksLostShare() : room.ticksLostShare();
		if (lostShare >= 0)
		{
			final int lost = session != null ? session.getTicksLost()
				: raid != null ? raid.getTicksLost() : room.getTicksLost();
			line("Ticks lost", String.format("%d (%.0f%%)", lost, lostShare * 100));

			final int eating = session != null ? session.getTicksLostEating()
				: raid != null ? raid.getTicksLostEating() : room.getTicksLostEating();
			if (eating > 0)
			{
				line("  to eating", String.valueOf(eating));
			}
		}

		panelComponent.setPreferredSize(new Dimension(
			Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, contentWidth + PADDING)), 0));
		return super.render(graphics);
	}

	/**
	 * One row, measured as it is added. Both halves are drawn on the same line
	 * with the right one flush to the edge, so the row needs the sum of them.
	 */
	private void line(String left, String right)
	{
		contentWidth = Math.max(contentWidth,
			metrics.stringWidth(left == null ? "" : left) + metrics.stringWidth(right == null ? "" : right));
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.right(right)
			.build());
	}

	/**
	 * What is being reported on. A raid names itself and how far in it is; a
	 * room names itself, which for a grouped room is the room rather than
	 * whichever of its NPCs happens to be dying.
	 */
	private static String title(SessionTotals session, Raid raid, Encounter room, Fight fight)
	{
		if (session != null)
		{
			return String.format("Trip: %d kill%s", session.getKills(), session.getKills() == 1 ? "" : "s");
		}
		if (raid != null)
		{
			return String.format("%s: %d room%s", raid.getName(),
				raid.getEncounters().size(), raid.getEncounters().size() == 1 ? "" : "s");
		}
		return room == null ? fight.getTargetName() : room.getName();
	}
}

package com.pvmperformance;

import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;

// Which special the Great Olm is running this phase.
enum OlmPhase
{
	ACID("acid"),
	FLAME("flame"),
	CRYSTAL("crystal");

	private final String label;

	OlmPhase(String label)
	{
		this.label = label;
	}

	String getLabel()
	{
		return label;
	}

	/** The phase an object marks, or null if the object says nothing. */
	static OlmPhase forObject(int objectId)
	{
		if (objectId == ObjectID.OLM_ACID_POOL)
		{
			return ACID;
		}
		if (objectId == ObjectID.OLM_CRYSTAL_BOMB
			|| objectId == ObjectID.OLM_CRYSTAL_ATTACK_SMALL
			|| objectId == ObjectID.OLM_CRYSTAL_ATTACK_LARGE)
		{
			return CRYSTAL;
		}
		return null;
	}

	/** The phase an NPC marks. Only the flame wall, which is an NPC of its own. */
	static OlmPhase forNpc(int npcId)
	{
		return npcId == NpcID.OLM_FIREWALL_NPC ? FLAME : null;
	}

	/** Whether this object is Olm's head, whose spawning begins a phase. */
	static boolean isHeadObject(int objectId)
	{
		return objectId == ObjectID.OLM_HEAD || objectId == ObjectID.OLM_HEAD_SPAWNING;
	}
}

package com.pvmperformance;

import net.runelite.api.Skill;

// The melee boost a player means to be holding, chosen in the config and used as the standard the efficiency figure
// measures against.
//
// Raid doses are deliberately absent here and from the other two: an overload or a dose of salts is detected from its
// own timer while it is running, and raises the standard on its own. Offering them as a goal would ask the player to
// declare something the game already says.
public enum MeleeBoost
{
	NONE("None")
		{
			@Override
			int boost(Skill skill, int base)
			{
				return 0;
			}
		},

	SUPER_COMBAT("Super combat")
		{
			@Override
			int boost(Skill skill, int base)
			{
				return base * 15 / 100 + 5;
			}
		},

	// Strength only. Attack is left alone, so a player on super strength is not marked down for an attack boost they never
	// meant to take.
	SUPER_STRENGTH("Super strength")
		{
			@Override
			int boost(Skill skill, int base)
			{
				return skill == Skill.STRENGTH ? base * 15 / 100 + 5 : 0;
			}
		};

	private final String displayName;

	MeleeBoost(String displayName)
	{
		this.displayName = displayName;
	}

	abstract int boost(Skill skill, int base);

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.pvmperformance;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.plugins.party.messages.StatusUpdate;

// The highest hitpoints level in the party, which is what Chambers of Xeric scales its monsters by.
@Singleton
class PartyHitpoints
{
	private final Client client;

	// party member id -> the maximum hitpoints they last reported.
	private final Map<Long, Integer> reported = new HashMap<>();

	@Inject
	PartyHitpoints(Client client)
	{
		this.client = client;
	}

	/**
	 * Takes a member's maximum hitpoints from a party status update. The updates
	 * carry only what has changed, so most say nothing about hitpoints and every
	 * field has to be read as possibly absent.
	 */
	void onStatusUpdate(StatusUpdate update)
	{
		final Integer max = update.getHealthMax();
		if (max != null && max > 0)
		{
			reported.put(update.getMemberId(), max);
		}
	}

	void forget(long memberId)
	{
		reported.remove(memberId);
	}

	void clear()
	{
		reported.clear();
	}

	/** The highest hitpoints level known, never below the player's own. */
	int highest()
	{
		int highest = client.getRealSkillLevel(Skill.HITPOINTS);
		for (Integer max : reported.values())
		{
			if (max > highest)
			{
				highest = max;
			}
		}
		return highest;
	}
}

package com.pvmperformance;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.QuantityFormatter;

class PvmPerformancePanel extends PluginPanel
{
	private static final String ALL_NPCS = "All NPCs";

	private final PvmPerformancePlugin plugin;

	private final JCheckBox bossOnly = new JCheckBox("Boss only");
	private final JTextField search = new JTextField();
	private final JComboBox<String> bossSelect = new JComboBox<>();
	private final JLabel status = new JLabel(" ");
	private final JPanel list = new JPanel();

	PvmPerformancePanel(PvmPerformancePlugin plugin)
	{
		super(false);
		this.plugin = plugin;

		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new BorderLayout(0, 8));

		add(buildHeader(), BorderLayout.NORTH);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		final JPanel wrap = new JPanel(new BorderLayout());
		wrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrap.add(list, BorderLayout.NORTH);
		final JScrollPane scroll = new JScrollPane(wrap,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(new EmptyBorder(0, 0, 0, 0));
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(scroll, BorderLayout.CENTER);

		refresh();
	}

	private JPanel buildHeader()
	{
		final JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JLabel title = new JLabel("PvM Performance");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(LEFT_ALIGNMENT);
		header.add(title);
		header.add(Box.createVerticalStrut(8));

		search.setToolTipText("Filter the list by NPC name");
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				refresh();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				refresh();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				refresh();
			}
		});
		fullWidth(header, search);
		header.add(Box.createVerticalStrut(6));

		bossSelect.addItem(ALL_NPCS);
		for (String boss : plugin.getBossDisplayNames())
		{
			bossSelect.addItem(boss);
		}
		bossSelect.setToolTipText("Jump to a boss (shows its stats, or 'no data' if not fought)");
		bossSelect.addActionListener(e -> refresh());
		fullWidth(header, bossSelect);
		header.add(Box.createVerticalStrut(6));

		final JButton exportAll = new JButton("Export all");
		exportAll.setToolTipText("Export every tracked fight to a CSV file");
		exportAll.addActionListener(e -> plugin.exportAll(bossOnly.isSelected()));

		final JButton clear = new JButton("Clear");
		clear.setToolTipText("Discard the tracked fight history");
		clear.addActionListener(e ->
		{
			plugin.clearHistory();
			refresh();
		});

		final JButton resetTrip = new JButton("New trip");
		resetTrip.setToolTipText("Start the whole-trip overlay totals over. "
			+ "Tracked fight history is untouched");
		resetTrip.addActionListener(e -> plugin.resetSession());

		// Its own row rather than a fourth column: four buttons across a side panel leaves each of them too narrow to read,
		// and this one is pressed after something looked wrong rather than as part of the routine.
		final JButton saveLog = new JButton("Save debug log");
		saveLog.setToolTipText("Write the last few thousand lines of what the tracker saw to a file, "
			+ "with the loadout and settings that produced them. Press it when a figure looks wrong");
		saveLog.addActionListener(e -> plugin.saveDebugLog());

		final JPanel buttons = new JPanel(new GridLayout(1, 3, 6, 0));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		buttons.add(exportAll);
		buttons.add(resetTrip);
		buttons.add(clear);
		fullWidth(header, buttons);
		header.add(Box.createVerticalStrut(4));
		fullWidth(header, saveLog);
		header.add(Box.createVerticalStrut(4));

		bossOnly.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bossOnly.setForeground(Color.WHITE);
		bossOnly.setToolTipText("Show and export only NPCs above the boss HP threshold");
		bossOnly.addActionListener(e -> refresh());
		fullWidth(header, bossOnly);

		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		status.setAlignmentX(LEFT_ALIGNMENT);
		header.add(status);

		return header;
	}

	private static void fullWidth(JPanel box, JComponent c)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		box.add(c);
	}

	void setStatus(String text)
	{
		SwingUtilities.invokeLater(() ->
		{
			status.setText(text);
			status.setToolTipText(text);
		});
	}

	void refresh()
	{
		SwingUtilities.invokeLater(() ->
		{
			list.removeAll();

			// A specific boss picked in the selector focuses the panel on it.
			final Object selected = bossSelect.getSelectedItem();
			if (selected != null && !ALL_NPCS.equals(selected))
			{
				final String bossName = selected.toString();
				NpcStats match = null;
				for (NpcStats s : plugin.getNpcStats(false))
				{
					if (s.getName().equalsIgnoreCase(bossName))
					{
						match = s;
						break;
					}
				}
				if (match != null)
				{
					list.add(buildRow(match));
				}
				else
				{
					final JLabel none = new JLabel("<html>No data for <b>" + bossName + "</b> yet.</html>");
					none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
					none.setBorder(new EmptyBorder(4, 2, 4, 2));
					list.add(none);
				}
				list.revalidate();
				list.repaint();
				return;
			}

			final String query = search.getText().trim().toLowerCase();
			int shown = 0;
			for (NpcStats s : plugin.getNpcStats(bossOnly.isSelected()))
			{
				if (!query.isEmpty() && !s.getName().toLowerCase().contains(query))
				{
					continue;
				}
				list.add(buildRow(s));
				list.add(Box.createVerticalStrut(4));
				shown++;
			}
			if (shown == 0)
			{
				final JLabel empty = new JLabel(query.isEmpty()
					? "<html>No fights tracked yet. Fight an NPC and it will show up here.</html>"
					: "<html>No tracked NPC matches that name.</html>");
				empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				empty.setBorder(new EmptyBorder(4, 2, 4, 2));
				list.add(empty);
			}
			list.revalidate();
			list.repaint();
		});
	}

	/**
	 * The efficiency and tick loss line, left off entirely when neither was
	 * measured: an empty pair of dashes reads as a bad score rather than none.
	 */
	private static String quality(NpcStats s)
	{
		final double efficiency = s.efficiency();
		final double lost = s.ticksLostShare();
		if (efficiency < 0 && lost < 0)
		{
			return "";
		}
		final StringBuilder line = new StringBuilder("<br><font color='#a0a0a0'>");
		if (efficiency >= 0)
		{
			line.append(String.format("%.0f%% efficiency", efficiency * 100));
		}
		if (lost >= 0)
		{
			if (efficiency >= 0)
			{
				line.append(" &middot; ");
			}
			line.append(String.format("%.0f%% ticks lost", lost * 100));
		}
		return line.append("</font>").toString();
	}

	private JPanel buildRow(NpcStats s)
	{
		final JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(6, 8, 6, 8));

		// Two lines: what was fought, then how well. Efficiency and lost ticks say where to improve, so they go where the eye
		// lands after the totals.
		final String info = String.format(
			"<html><b>%s</b><br><font color='#a0a0a0'>%d fights &middot; %d kills &middot; "
				+ "%.2f avg hit &middot; %.0f%% acc &middot; %s dmg</font>%s</html>",
			s.getName(), s.getFights(), s.getKills(), s.avgHit(), s.accuracy() * 100,
			QuantityFormatter.formatNumber(s.getTotalDamageDealt()),
			quality(s));
		final JLabel label = new JLabel(info);
		label.setForeground(Color.WHITE);
		row.add(label, BorderLayout.CENTER);

		final JButton export = new JButton("CSV");
		export.setToolTipText("Export " + s.getName() + " fights to CSV");
		export.setMargin(new java.awt.Insets(2, 6, 2, 6));
		export.addActionListener(e -> plugin.exportNpc(s.getName()));
		row.add(export, BorderLayout.EAST);

		// Height capped only now that the row holds something. Asked before the label and the button went in, the preferred
		// height is an empty panel's - the border and nothing else - and the row is pinned to twelve pixels with its contents
		// clipped away.
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}
}

package com.pvmperformance;

import lombok.Getter;

// Running totals for the current trip, so the overlay can show how a session went rather than resetting at each kill.
// One unlucky kill says little.
@Getter
class SessionTotals
{
	private long startMillis;
	private long lastActivityMillis;
	private long firstActivityMillis;
	private int fights;
	private int kills;
	private int damageDealt;
	private int attempts;
	private int targets;
	private int hits;
	// Attacks that went out and never resolved, because the target died or changed form in flight. Not misses; see
	// Fight.recordAttackNulled.
	private int nulled;
	private int attacksMade;
	private int attacksPrayed;
	private int attacksPotted;
	// Attacks thrown with nothing better available to switch into. The gap to attacksMade is the number that missed at
	// least one switch.
	private int attacksSwitched;
	private double sumActualSetup;
	private double sumIdealSetup;
	private int ticksLostEating;
	private int ticksLostOther;
	private int combatTicks;
	// Running totals of what each attack was expected to do, so the measured side can be compared against the sum of every
	// weapon's own contribution.
	private double sumExpectedAccuracy;
	private double sumExpectedAverageHit;

	SessionTotals(long now)
	{
		this.startMillis = now;
		this.lastActivityMillis = now;
	}

	void reset(long now)
	{
		startMillis = now;
		lastActivityMillis = now;
		firstActivityMillis = 0;
		fights = 0;
		kills = 0;
		damageDealt = 0;
		attempts = 0;
		targets = 0;
		hits = 0;
		nulled = 0;
		attacksMade = 0;
		attacksPrayed = 0;
		attacksPotted = 0;
		attacksSwitched = 0;
		sumActualSetup = 0;
		sumIdealSetup = 0;
		ticksLostEating = 0;
		ticksLostOther = 0;
		combatTicks = 0;
		sumExpectedAccuracy = 0;
		sumExpectedAverageHit = 0;
	}

	void recordFightEnded(boolean died, Fight fight, long now)
	{
		fights++;
		if (died)
		{
			kills++;
		}
		noteActivity(now);
	}

	// Books a tick that passed with the weapon off cooldown and no attack made.
	void recordTickLost(boolean eating)
	{
		if (eating)
		{
			ticksLostEating++;
		}
		else
		{
			ticksLostOther++;
		}
		combatTicks++;
	}

	/** A tick that passed while the weapon was still on cooldown. */
	void recordTickSpent()
	{
		combatTicks++;
	}

	/** Damage from one hitsplat; see {@code Fight.recordDamageDealt}. */
	void recordAttempt(int damage, boolean landedAttack, long now)
	{
		damageDealt += damage;
		if (landedAttack)
		{
			hits++;
		}
		noteActivity(now);
	}

	/**
	 * Adds what this attack was expected to do. The max hit is not accumulated:
	 * it is a property of the loadout rather than something that adds up.
	 */
	void recordAttackMade(boolean potted)
	{
		attacksMade++;
		combatTicks++;
		attempts++;
		targets++;
		if (potted)
		{
			attacksPotted++;
		}
	}

	void recordAttackNulled()
	{
		nulled++;
	}

	/** See {@code Fight.recordExtraTarget}: another npc caught by one throw. */
	void recordExtraTarget(int damage, boolean newTarget, boolean landed, long now)
	{
		damageDealt += damage;
		if (newTarget)
		{
			targets++;
		}
		if (landed)
		{
			hits++;
		}
		noteActivity(now);
	}

	/** Attacks that actually got an answer, which is what the damage divides by. */
	int resolvedAttempts()
	{
		return Math.max(0, attempts - nulled);
	}

	/** Npcs reached; see {@code Fight.resolvedTargets}. Never reduced by the nulled attacks. */
	int resolvedTargets()
	{
		return targets;
	}

	double accuracy()
	{
		final int resolved = resolvedTargets();
		return resolved == 0 ? 0 : (double) hits / resolved;
	}

	void recordAttackResolved(boolean prayed, boolean switched, double actualSetup, double idealSetup)
	{
		if (prayed)
		{
			attacksPrayed++;
		}
		if (switched)
		{
			attacksSwitched++;
		}
		if (actualSetup >= 0 && idealSetup > 0)
		{
			sumActualSetup += actualSetup;
			sumIdealSetup += idealSetup;
		}
	}

	double efficiency()
	{
		return sumIdealSetup <= 0 ? -1 : sumActualSetup / sumIdealSetup;
	}

	void recordExpected(double accuracy, double averageHit)
	{
		if (accuracy >= 0 && averageHit >= 0)
		{
			sumExpectedAccuracy += accuracy;
			sumExpectedAverageHit += averageHit;
		}
	}

	/**
	 * How long the trip has run, from its first attack rather than from when the
	 * plugin started.
	 */
	long durationMillis()
	{
		return firstActivityMillis == 0 ? 0
			: Math.max(0, lastActivityMillis - firstActivityMillis);
	}

	// Stamped by the first thing that happens rather than at construction, so the trip reads no time at all until the
	// first attack.
	private void noteActivity(long now)
	{
		if (firstActivityMillis == 0)
		{
			firstActivityMillis = now;
		}
		lastActivityMillis = now;
	}

	int getTicksLost()
	{
		return ticksLostEating + ticksLostOther;
	}

	double ticksLostShare()
	{
		return combatTicks <= 0 ? -1 : (double) getTicksLost() / combatTicks;
	}
}

package com.pvmperformance;

import java.util.ArrayList;
import java.util.List;
import lombok.Getter;

// One boss or room: the fights that belong together, kept as a list rather than as a second set of counters.
@Getter
class Encounter
{
	private final String name;
	private final RaidType raid;
	private final long startMillis;
	private final List<Fight> fights = new ArrayList<>();
	private long endMillis;

	Encounter(String name, RaidType raid, long now)
	{
		this.name = name;
		this.raid = raid;
		this.startMillis = now;
	}

	void add(Fight fight)
	{
		fights.add(fight);
	}

	/** Whether a fight on this NPC continues this encounter or starts another. */
	boolean accepts(String candidateName)
	{
		return name.equals(candidateName);
	}

	void end(long now)
	{
		endMillis = now;
	}

	/**
	 * Whether killing this NPC is killing what this room is about. Asked of the
	 * group rather than the id: a boss made of several NPCs is killed at whichever
	 * part is last, and the Hueycoatl drops its loot from a head while the room is
	 * full of fights against body segments.
	 */
	boolean holds(int npcId)
	{
		for (Fight fight : fights)
		{
			if (fight.getTargetId() == npcId || EncounterGroup.sameGroup(npcId, fight.getTargetId()))
			{
				return true;
			}
		}
		return false;
	}

	boolean isEnded()
	{
		return endMillis > 0;
	}

	/**
	 * Whether anything in this room has been attacked yet. Latched rather than
	 * counted, so the answer is the same after the fight that did it has been
	 * replaced - which is the whole point of asking the room instead of the
	 * fight - and so it costs nothing on a room holding hundreds of them.
	 */
	private boolean engaged;

	void noteAttack()
	{
		engaged = true;
	}

	boolean isEngaged()
	{
		return engaged;
	}

	/**
	 * Whether anything has been thrown in this room yet. A fight opens on merely
	 * looking at something, so a room with no attempts is one nothing happened in.
	 */
	boolean hasAttempts()
	{
		for (Fight fight : fights)
		{
			if (fight.getAttempts() > 0)
			{
				return true;
			}
		}
		return false;
	}

	/** Whether any of this encounter's targets died. */
	boolean isKilled()
	{
		for (Fight fight : fights)
		{
			if (fight.isTargetDied())
			{
				return true;
			}
		}
		return false;
	}

	int getDamageDealt()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			if (fight.isScored())
			{
				total += fight.getDamageDealt();
			}
		}
		return total;
	}

	int getDamageTaken()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			total += fight.getDamageTaken();
		}
		return total;
	}

	/**
	 * Attacks that got an answer. One nulled by the kill has no outcome to be
	 * right or wrong about, and left in here it reads as a miss that dealt
	 * nothing.
	 */
	int getAttempts()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			if (fight.isScored())
			{
				total += fight.resolvedAttempts();
			}
		}
		return total;
	}

	int getHits()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			if (fight.isScored())
			{
				total += fight.getHits();
			}
		}
		return total;
	}

	/** Npcs this room's attacks reached, which accuracy divides by. */
	int getTargets()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			if (fight.isScored())
			{
				total += fight.resolvedTargets();
			}
		}
		return total;
	}

	double accuracy()
	{
		final int targets = getTargets();
		return targets == 0 ? 0 : (double) getHits() / targets;
	}

	double averageHit()
	{
		final int attempts = getAttempts();
		return attempts == 0 ? 0 : (double) getDamageDealt() / attempts;
	}

	/** Running total of what each attack was expected to deal, or 0 if untracked. */
	double sumExpectedAverageHit()
	{
		double total = 0;
		for (Fight fight : fights)
		{
			if (fight.isScored())
			{
				total += fight.getSumExpectedAverageHit();
			}
		}
		return total;
	}

	double sumExpectedAccuracy()
	{
		double total = 0;
		for (Fight fight : fights)
		{
			if (fight.isScored())
			{
				total += fight.getSumExpectedAccuracy();
			}
		}
		return total;
	}

	int getAttacksMade()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			if (fight.isScored())
			{
				total += fight.getAttacksMade();
			}
		}
		return total;
	}

	int getAttacksPrayed()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			if (fight.isScored())
			{
				total += fight.getAttacksPrayed();
			}
		}
		return total;
	}

	int getAttacksSwitched()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			if (fight.isScored())
			{
				total += fight.getAttacksSwitched();
			}
		}
		return total;
	}

	int getAttacksPotted()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			if (fight.isScored())
			{
				total += fight.getAttacksPotted();
			}
		}
		return total;
	}

	double efficiency()
	{
		double actual = 0;
		double ideal = 0;
		for (Fight fight : fights)
		{
			if (fight.isScored())
			{
				actual += fight.getSumActualSetup();
				ideal += fight.getSumIdealSetup();
			}
		}
		return ideal <= 0 ? -1 : actual / ideal;
	}

	int getTicksLostEating()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			total += fight.getTicksLostEating();
		}
		return total;
	}

	int getTicksLost()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			total += fight.getTicksLost();
		}
		return total;
	}

	int getCombatTicks()
	{
		int total = 0;
		for (Fight fight : fights)
		{
			total += fight.getCombatTicks();
		}
		return total;
	}

	double ticksLostShare()
	{
		final int ticks = getCombatTicks();
		return ticks <= 0 ? -1 : (double) getTicksLost() / ticks;
	}

	long durationMillis()
	{
		long last = startMillis;
		for (Fight fight : fights)
		{
			last = Math.max(last, fight.getLastActivityMillis());
		}
		return Math.max(0, (isEnded() ? endMillis : last) - startMillis);
	}
}

