			NpcID.TOA_PATH_APMEKEN_BABOON_MAGIC_1, NpcID.TOA_PATH_APMEKEN_BABOON_MAGIC_2,
			NpcID.TOA_PATH_APMEKEN_BABOON_SHAMAN, NpcID.TOA_PATH_APMEKEN_BABOON_ZOMBIE,
			NpcID.TOA_PATH_APMEKEN_BABOON_CURSED, NpcID.TOA_PATH_APMEKEN_BABOON_THRALL);

		// Theatre of Blood. The nylocas group by style, big with small: one colour is one job. Both the incoming form and the
		// fighting form it becomes are listed - with only the incoming ones, every nylocas killed after it settled reported
		// itself.
		put(groups, "Nylocas (melee)",
			NpcID.TOB_NYLOCAS_INCOMING_MELEE, NpcID.TOB_NYLOCAS_BIG_INCOMING_MELEE,
			NpcID.TOB_NYLOCAS_FIGHTING_MELEE, NpcID.TOB_NYLOCAS_BIG_FIGHTING_MELEE,
			NpcID.TOB_NYLOCAS_INCOMING_MELEE_STORY, NpcID.TOB_NYLOCAS_BIG_INCOMING_MELEE_STORY,
			NpcID.TOB_NYLOCAS_FIGHTING_MELEE_STORY, NpcID.TOB_NYLOCAS_BIG_FIGHTING_MELEE_STORY,
			NpcID.TOB_NYLOCAS_INCOMING_MELEE_HARD, NpcID.TOB_NYLOCAS_BIG_INCOMING_MELEE_HARD,
			NpcID.TOB_NYLOCAS_FIGHTING_MELEE_HARD, NpcID.TOB_NYLOCAS_BIG_FIGHTING_MELEE_HARD);

		put(groups, "Nylocas (ranged)",
			NpcID.TOB_NYLOCAS_INCOMING_RANGED, NpcID.TOB_NYLOCAS_BIG_INCOMING_RANGED,
			NpcID.TOB_NYLOCAS_FIGHTING_RANGED, NpcID.TOB_NYLOCAS_BIG_FIGHTING_RANGED,
			NpcID.TOB_NYLOCAS_INCOMING_RANGED_STORY, NpcID.TOB_NYLOCAS_BIG_INCOMING_RANGED_STORY,
			NpcID.TOB_NYLOCAS_FIGHTING_RANGED_STORY, NpcID.TOB_NYLOCAS_BIG_FIGHTING_RANGED_STORY,
			NpcID.TOB_NYLOCAS_INCOMING_RANGED_HARD, NpcID.TOB_NYLOCAS_BIG_INCOMING_RANGED_HARD,
			NpcID.TOB_NYLOCAS_FIGHTING_RANGED_HARD, NpcID.TOB_NYLOCAS_BIG_FIGHTING_RANGED_HARD);

		put(groups, "Nylocas (magic)",
			NpcID.TOB_NYLOCAS_INCOMING_MAGIC, NpcID.TOB_NYLOCAS_BIG_INCOMING_MAGIC,
			NpcID.TOB_NYLOCAS_FIGHTING_MAGIC, NpcID.TOB_NYLOCAS_BIG_FIGHTING_MAGIC,
			NpcID.TOB_NYLOCAS_INCOMING_MAGIC_STORY, NpcID.TOB_NYLOCAS_BIG_INCOMING_MAGIC_STORY,
			NpcID.TOB_NYLOCAS_FIGHTING_MAGIC_STORY, NpcID.TOB_NYLOCAS_BIG_FIGHTING_MAGIC_STORY,
			NpcID.TOB_NYLOCAS_INCOMING_MAGIC_HARD, NpcID.TOB_NYLOCAS_BIG_INCOMING_MAGIC_HARD,
			NpcID.TOB_NYLOCAS_FIGHTING_MAGIC_HARD, NpcID.TOB_NYLOCAS_BIG_FIGHTING_MAGIC_HARD);

		// The boss rotates its style rather than being one of them, so it is its own room rather than three.
		put(groups, "Nylocas Vasilias",
			NpcID.NYLOCAS_BOSS_SPAWNING, NpcID.NYLOCAS_BOSS_MELEE, NpcID.NYLOCAS_BOSS_MAGIC,
			NpcID.NYLOCAS_BOSS_RANGED, NpcID.NYLOCAS_BOSS_SPAWNING_STORY, NpcID.NYLOCAS_BOSS_MELEE_STORY,
			NpcID.NYLOCAS_BOSS_MAGIC_STORY, NpcID.NYLOCAS_BOSS_RANGED_STORY,
			NpcID.NYLOCAS_BOSS_SPAWNING_HARD, NpcID.NYLOCAS_BOSS_MELEE_HARD,
			NpcID.NYLOCAS_BOSS_MAGIC_HARD, NpcID.NYLOCAS_BOSS_RANGED_HARD);

		// Hard mode only.
		put(groups, "Nylocas Prinkipas",
			NpcID.NYLOCAS_MINIBOSS_SPAWNING_HARD, NpcID.NYLOCAS_MINIBOSS_MELEE_HARD,
			NpcID.NYLOCAS_MINIBOSS_MAGIC_HARD, NpcID.NYLOCAS_MINIBOSS_RANGED_HARD);

		// Healing off the exhumeds, standing, and staring are one fight.
		put(groups, "Xarpus",
			NpcID.TOB_XARPUS_STATIC, NpcID.TOB_XARPUS_FEEDING, NpcID.TOB_XARPUS_COMBAT,
			NpcID.TOB_XARPUS_STATIC_STORY, NpcID.TOB_XARPUS_FEEDING_STORY, NpcID.TOB_XARPUS_COMBAT_STORY,
			NpcID.TOB_XARPUS_STATIC_HARD, NpcID.TOB_XARPUS_FEEDING_HARD, NpcID.TOB_XARPUS_COMBAT_HARD);

		// Three phases across two wardens, their obelisks and cores. The four statues named for the path bosses are scenery,
		// and nothing should rest on a name alone.
		put(groups, "Wardens",
			NpcID.TOA_WARDENS_P1_OBELISK_NPC, NpcID.TOA_WARDENS_P2_OBELISK_NPC,
			NpcID.TOA_WARDEN_ELIDINIS_PHASE1, NpcID.TOA_WARDEN_TUMEKEN_PHASE1,
			NpcID.TOA_WARDEN_ELIDINIS_PHASE1_INACTIVE, NpcID.TOA_WARDEN_TUMEKEN_PHASE1_INACTIVE,
			NpcID.TOA_WARDEN_ELIDINIS_PHASE2_MAGE, NpcID.TOA_WARDEN_ELIDINIS_PHASE2_RANGE,
			NpcID.TOA_WARDEN_ELIDINIS_PHASE2_EXPOSED, NpcID.TOA_WARDEN_TUMEKEN_PHASE2_MAGE,
			NpcID.TOA_WARDEN_TUMEKEN_PHASE2_RANGE, NpcID.TOA_WARDEN_TUMEKEN_PHASE2_EXPOSED,
			NpcID.TOA_WARDEN_ELIDINIS_PHASE3, NpcID.TOA_WARDEN_TUMEKEN_PHASE3,
			NpcID.TOA_WARDEN_ELIDINIS_PHASE3_INACTIVE, NpcID.TOA_WARDEN_TUMEKEN_PHASE3_INACTIVE,
			NpcID.TOA_WARDEN_ELIDINIS_PHASE3_CHARGING, NpcID.TOA_WARDEN_TUMEKEN_PHASE3_CHARGING,
			NpcID.TOA_WARDEN_ELIDINIS_CORE, NpcID.TOA_WARDEN_TUMEKEN_CORE, NpcID.TOA_WARDENS_ENERGY);

		put(groups, "Ba-Ba",
			NpcID.TOA_BABA, NpcID.TOA_BABA_DIGGING, NpcID.TOA_BABA_BABOON, NpcID.TOA_BABA_BOULDER,
			NpcID.TOA_BABA_BOULDER_WEAK);

		// The Hueycoatl is one snake in many pieces - a head that changes id as it is broken, enraged and defeated, a tail
		// that breaks, and the body segments between - all attacked as one fight. Without this the overlay reset on every
		// part hit: eighteen fights in a trip and never a kill. Hespori and its flowers are one fight for the same reason.
		put(groups, "Hespori",
			NpcID.HESPORI, NpcID.HESPORI_HEALER_ACTIVE, NpcID.HESPORI_HEALER_INACTIVE);
		put(groups, "Hespori (A Night at the Theatre)",
			NpcID.TOBQUEST_HESPORI, NpcID.TOBQUEST_HESPORI_HEALER_ACTIVE,
			NpcID.TOBQUEST_HESPORI_HEALER_INACTIVE);
		put(groups, "The Hueycoatl",
			NpcID.HUEY_HEAD, NpcID.HUEY_HEAD_INVULNERABLE, NpcID.HUEY_HEAD_DEFEATED,
			NpcID.HUEY_HEAD_ENRAGED, NpcID.HUEY_TAIL, NpcID.HUEY_TAIL_BROKEN,
			NpcID.HUEY_BODY_PART, NpcID.HUEY_BODY_PART_BROKEN);

		// The meat tree is the healing mechanic, as Vasa's crystals are.
		put(groups, "Muttadiles",
			NpcID.RAIDS_DOGODILE, NpcID.RAIDS_DOGODILE_SUBMERGED, NpcID.RAIDS_DOGODILE_JUNIOR,
			NpcID.RAIDS_DOGODILE_MEAT_TREE);

		// Maiden takes her own adds: the matomenos and the blood spawns. Verzik's blood nylocas share the matomenos name but
		// not its id, and stay out.
		put(groups, "The Maiden of Sugadinti",
			NpcID.TOB_MAIDEN_100, NpcID.TOB_MAIDEN_70, NpcID.TOB_MAIDEN_50, NpcID.TOB_MAIDEN_30,
			NpcID.TOB_MAIDEN_100_STORY, NpcID.TOB_MAIDEN_70_STORY,
			NpcID.TOB_MAIDEN_50_STORY, NpcID.TOB_MAIDEN_30_STORY,
			NpcID.TOB_MAIDEN_100_HARD, NpcID.TOB_MAIDEN_70_HARD,
			NpcID.TOB_MAIDEN_50_HARD, NpcID.TOB_MAIDEN_30_HARD,
			NpcID.MAIDEN_ELEMENTAL, NpcID.MAIDEN_ELEMENTAL_STORY, NpcID.MAIDEN_ELEMENTAL_HARD,
			NpcID.MAIDEN_BLOOD_SLUG, NpcID.MAIDEN_BLOOD_SLUG_STORY, NpcID.MAIDEN_BLOOD_SLUG_HARD);

		return Collections.unmodifiableMap(groups);
	}

	private static Set<Integer> buildIgnored()
	{
		return Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
			NpcID.TOA_ZEBAK_JUG, NpcID.TOA_ZEBAK_JUG_ROLLING,
			// Hueycoatl scenery rather than the snake: the head's respawn placeholder, the tail's projectile, and the phase two
			// health bar pillar.
			NpcID.HUEY_HEAD_RESPAWN_PLACEHOLDER, NpcID.HUEY_TAIL_PROJECTILE,
			NpcID.HUEY_P2_PILLAR_HEADBAR_INVIS,
			// The Wardens' energy siphons - the skulls in phase two. They are a mechanic to be broken, not a thing to be
			// scored against: each one opens its own fight and then sits on the overlay in place of the raid you are in.
			NpcID.TOA_WARDENS_ENERGY,
			// And the seer, which stands in that fight and is not part of it. Something on the phase change puts a single
			// point of damage on it that isMine() reports as the player's, and that opened a fight, booked an attack and
			// counted a kill: nine of each in one trip against an npc nobody had touched. Named outright rather than left
			// to the fightable test, because that test can only ask what the game says about it and the answer was enough
			// to get through once already.
			NpcID.HUEY_SEER)));
	}

	/**
	 * Whether this is one of the totems, whose ids both Nightmares share. Which
	 * fight one belongs to is decided by the boss standing in the room.
	 */
	static boolean isNightmareTotem(int npcId)
	{
		switch (npcId)
		{
			case NpcID.NIGHTMARE_TOTEM_1_READY:
			case NpcID.NIGHTMARE_TOTEM_2_READY:
			case NpcID.NIGHTMARE_TOTEM_3_READY:
			case NpcID.NIGHTMARE_TOTEM_4_READY:
			case NpcID.NIGHTMARE_TOTEM_1_CHARGED:
			case NpcID.NIGHTMARE_TOTEM_2_CHARGED:
			case NpcID.NIGHTMARE_TOTEM_3_CHARGED:
			case NpcID.NIGHTMARE_TOTEM_4_CHARGED:
				return true;
			default:
				return false;
		}
	}

	/** Which Nightmare this NPC is a form of, or null if it is not one. */
	static String nightmareBossName(int npcId)
	{
		if (isNightmareTotem(npcId))
		{
			return null;
		}
		final String group = GROUPS.get(npcId);
		return "The Nightmare".equals(group) || "Phosani's Nightmare".equals(group) ? group : null;
	}

	private static Set<Integer> buildUnscored()
	{
		return Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
			// Hespori's flowers heal it and die to one hit whatever is swung at them, so their accuracy is a formality and their
			// damage is a fraction of a real hit. Scored, they drag a kill's figures down for doing the thing the fight asks of
			// you. The ticks spent on them still count, which is the part that is genuinely on the player.
			NpcID.HESPORI_HEALER_ACTIVE,
			NpcID.HESPORI_HEALER_INACTIVE,
			NpcID.TOBQUEST_HESPORI_HEALER_ACTIVE,
			NpcID.TOBQUEST_HESPORI_HEALER_INACTIVE,
			NpcID.TOA_KEPHRI_SHIELD_SCARAB,
			// The Judge is Yama's own add. Grouped so killing it does not reset what is on screen, and unscored so it does not
			// lend its figures to his. Ignoring it outright would have been worse than either: with nothing tracking the Judge,
			// the time spent killing its 400 hitpoints would have been booked against Yama as ticks lost.
			NpcID.YAMA_JUDGE_OF_YAMA, NpcID.LEAGUE6_JUDGE_OF_YAMA,
			// Phosani's adds, killed in one hit apiece. Grouped rather than ignored, or the time spent on them would be booked
			// against her as ticks lost; unscored, or their guaranteed max hits would flatter whoever spent longest on them.
			NpcID.NIGHTMARE_CHALLENGE_HUSK_MAGIC, NpcID.NIGHTMARE_CHALLENGE_HUSK_RANGED,
			NpcID.NIGHTMARE_CHALLENGE_PARASITE, NpcID.NIGHTMARE_CHALLENGE_PARASITE_WEAK,
			NpcID.NIGHTMARE_CHALLENGE_SLEEPWALKER)));
	}

	/**
	 * Whether wearing this id means the boss has been beaten. A transform to it
	 * is a kill, which matters for a boss whose NPCs are never removed from the
	 * scene: the Hueycoatl's are not, so nothing despawns to end the fight.
	 */
	static boolean isDefeated(int npcId)
	{
		return DEFEATED.contains(npcId);
	}

	/**
	 * The Chambers' stone guardians, which only a pickaxe can hurt. All four ids
	 * on purpose: the gamevals read as left, right and their two dead forms,
	 * while the wiki's calculator reads the same four as a normal and a
	 * challenge mode pair. Both cannot be right and the disagreement is not
	 * settled here, so the whole block is claimed - the two that are the dead
	 * forms are already unattackable, and a multiplier on a corpse costs
	 * nothing, where a missing one on the live guardian silently drops the
	 * pickaxe rule in whichever mode is misread.
	 */
	static boolean isGuardian(int npcId)
	{
		return npcId == NpcID.RAIDS_STONEGUARDIANS_LEFT || npcId == NpcID.RAIDS_STONEGUARDIANS_RIGHT
			|| npcId == NpcID.RAIDS_STONEGUARDIANS_LEFT_DEAD || npcId == NpcID.RAIDS_STONEGUARDIANS_RIGHT_DEAD;
	}

	private static final Set<Integer> DEFEATED = Collections.unmodifiableSet(
		new HashSet<>(Collections.singletonList(NpcID.HUEY_HEAD_DEFEATED)));

	private static Set<Integer> buildUnattackable()
	{
		return Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
			// Verzik between phases.
			NpcID.VERZIK_PHASE1_TO2_TRANSITION, NpcID.VERZIK_PHASE2_TO3_TRANSITION,
			NpcID.VERZIK_PHASE1_TO2_TRANSITION_STORY, NpcID.VERZIK_PHASE2_TO3_TRANSITION_STORY,
			NpcID.VERZIK_PHASE1_TO2_TRANSITION_HARD, NpcID.VERZIK_PHASE2_TO3_TRANSITION_HARD,
			// The Wardens before they wake and while they charge.
			NpcID.TOA_WARDEN_ELIDINIS_PHASE1_INACTIVE, NpcID.TOA_WARDEN_TUMEKEN_PHASE1_INACTIVE,
			NpcID.TOA_WARDEN_ELIDINIS_PHASE3_INACTIVE, NpcID.TOA_WARDEN_TUMEKEN_PHASE3_INACTIVE,
			NpcID.TOA_WARDEN_ELIDINIS_PHASE3_CHARGING, NpcID.TOA_WARDEN_TUMEKEN_PHASE3_CHARGING,
			NpcID.TOA_WARDENS_P1_OBELISK_NPC_INACTIVE,
			// The Hueycoatl's head while it cannot be hurt, and once it is beaten. Named outright by the gameval, which is the
			// signal the suffixes are there to give.
			NpcID.HUEY_HEAD_INVULNERABLE, NpcID.HUEY_HEAD_DEFEATED,
			// Dead or dying, but still standing in the scene.
			NpcID.TOA_KEPHRI_BOSS_DEAD, NpcID.TOA_ZEBAK_DEAD,
			NpcID.OLM_HAND_LEFT_DYING, NpcID.OLM_HAND_RIGHT_DYING,
			NpcID.RAIDS_STONEGUARDIANS_LEFT_DEAD, NpcID.RAIDS_STONEGUARDIANS_RIGHT_DEAD,
			// The ice demon is only fightable once the brazier is lit, and Tekton cannot be touched while he is at his anvil
			// healing.
			NpcID.RAIDS_ICEDEMON_NONCOMBAT, NpcID.RAIDS_TEKTON_HAMMERING,
			// Sotetseg while the maze runs. Which of his two ids that is remains unconfirmed; see the note above. The tell is
			// his room reporting no tick loss at all.
			NpcID.TOB_SOTETSEG_NONCOMBAT, NpcID.TOB_SOTETSEG_NONCOMBAT_STORY,
			NpcID.TOB_SOTETSEG_NONCOMBAT_HARD,
			// A totem is only open once the shield behind it is broken.
			NpcID.NIGHTMARE_TOTEM_1_DORMANT, NpcID.NIGHTMARE_TOTEM_2_DORMANT,
			NpcID.NIGHTMARE_TOTEM_3_DORMANT, NpcID.NIGHTMARE_TOTEM_4_DORMANT,
			// Akkha vanishes for his memory blast. That these two ids are what he wears while gone is a guess from the name, and
			// free either way: if he despawns instead, the fight ends on its own and counts nothing.
			NpcID.AKKHA_ENRAGE_DUMMY, NpcID.AKKHA_SHADOW_ENRAGE_DUMMY,
			NpcID.TOB_MAIDEN_DYING_A, NpcID.TOB_MAIDEN_DYING_B,
			NpcID.TOB_MAIDEN_DYING_A_STORY, NpcID.TOB_MAIDEN_DYING_B_STORY,
			NpcID.TOB_MAIDEN_DYING_A_HARD, NpcID.TOB_MAIDEN_DYING_B_HARD,
			NpcID.XARPUS_DEATH, NpcID.XARPUS_DEATH_STORY, NpcID.XARPUS_DEATH_HARD,
			NpcID.TOA_WARDEN_P3_DEATH_ELIDINIS, NpcID.TOA_WARDEN_P3_DEATH_TUMEKEN)));
	}

	private static void put(Map<Integer, String> groups, String name, int... npcIds)
	{
		for (int id : npcIds)
		{
			groups.put(id, name);
		}
	}
}

package com.pvmperformance;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

// Combat spells and their base max hits, keyed by the value of VarbitID.AUTOCAST_SPELL while the spell is set to
// autocast. Ported from the LlemonDuck dps-calculator (BSD-2), (c) Paul Norton.
@Getter
@RequiredArgsConstructor
enum Spell
{
	// ancient spells
	ICE_BARRAGE(46, "Ice Barrage", 30, Spellbook.ANCIENT),
	BLOOD_BARRAGE(45, "Blood Barrage", 29, Spellbook.ANCIENT),
	SHADOW_BARRAGE(44, "Shadow Barrage", 28, Spellbook.ANCIENT),
	SMOKE_BARRAGE(43, "Smoke Barrage", 27, Spellbook.ANCIENT),
	ICE_BLITZ(42, "Ice Blitz", 26, Spellbook.ANCIENT),
	BLOOD_BLITZ(41, "Blood Blitz", 25, Spellbook.ANCIENT),
	SHADOW_BLITZ(40, "Shadow Blitz", 24, Spellbook.ANCIENT),
	SMOKE_BLITZ(39, "Smoke Blitz", 23, Spellbook.ANCIENT),
	ICE_BURST(38, "Ice Burst", 22, Spellbook.ANCIENT),
	BLOOD_BURST(37, "Blood Burst", 21, Spellbook.ANCIENT),
	SHADOW_BURST(36, "Shadow Burst", 18, Spellbook.ANCIENT),
	SMOKE_BURST(35, "Smoke Burst", 17, Spellbook.ANCIENT),
	ICE_RUSH(34, "Ice Rush", 16, Spellbook.ANCIENT),
	BLOOD_RUSH(33, "Blood Rush", 15, Spellbook.ANCIENT),
	SHADOW_RUSH(32, "Shadow Rush", 14, Spellbook.ANCIENT),
	SMOKE_RUSH(31, "Smoke Rush", 13, Spellbook.ANCIENT),

	// standard spells
	FIRE_SURGE(51, "Fire Surge", 24, Spellbook.STANDARD),
	EARTH_SURGE(50, "Earth Surge", 23, Spellbook.STANDARD),
	WATER_SURGE(49, "Water Surge", 22, Spellbook.STANDARD),
	WIND_SURGE(48, "Wind Surge", 21, Spellbook.STANDARD),
	FIRE_WAVE(16, "Fire Wave", 20, Spellbook.STANDARD),
	EARTH_WAVE(15, "Earth Wave", 19, Spellbook.STANDARD),
	WATER_WAVE(14, "Water Wave", 18, Spellbook.STANDARD),
	WIND_WAVE(13, "Wind Wave", 17, Spellbook.STANDARD),
	FIRE_BLAST(12, "Fire Blast", 16, Spellbook.STANDARD),
	EARTH_BLAST(11, "Earth Blast", 15, Spellbook.STANDARD),
	WATER_BLAST(10, "Water Blast", 14, Spellbook.STANDARD),
	WIND_BLAST(9, "Wind Blast", 13, Spellbook.STANDARD),
	FIRE_BOLT(8, "Fire Bolt", 12, Spellbook.STANDARD),
	EARTH_BOLT(7, "Earth Bolt", 11, Spellbook.STANDARD),
	WATER_BOLT(6, "Water Bolt", 10, Spellbook.STANDARD),
	WIND_BOLT(5, "Wind Bolt", 9, Spellbook.STANDARD),
	FIRE_STRIKE(4, "Fire Strike", 8, Spellbook.STANDARD),
	EARTH_STRIKE(3, "Earth Strike", 6, Spellbook.STANDARD),
	WATER_STRIKE(2, "Water Strike", 4, Spellbook.STANDARD),
	WIND_STRIKE(1, "Wind Strike", 2, Spellbook.STANDARD),

	// standard, but need a specific staff to autocast
	FLAMES_OF_ZAMORAK(20, "Flames of Zamorak", 20, Spellbook.STANDARD),
	CLAWS_OF_GUTHIX(-1, "Claws of Guthix", 20, Spellbook.STANDARD),
	SARADOMIN_STRIKE(-1, "Saradomin Strike", 20, Spellbook.STANDARD),
	CRUMBLE_UNDEAD(17, "Crumble Undead", 15, Spellbook.STANDARD),
	IBAN_BLAST(47, "Iban Blast", 25, Spellbook.STANDARD),
	MAGIC_DART(18, "Magic Dart", 10, Spellbook.STANDARD),

	// arceuus
	INFERIOR_DEMONBANE(53, "Inferior Demonbane", 16, Spellbook.ARCEUUS),
	SUPERIOR_DEMONBANE(54, "Superior Demonbane", 23, Spellbook.ARCEUUS),
	DARK_DEMONBANE(55, "Dark Demonbane", 30, Spellbook.ARCEUUS),
	GHOSTLY_GRASP(56, "Ghostly Grasp", 12, Spellbook.ARCEUUS),
	SKELETAL_GRASP(57, "Skeletal Grasp", 17, Spellbook.ARCEUUS),
	UNDEAD_GRASP(58, "Undead Grasp", 24, Spellbook.ARCEUUS);

	// Elemental spells rose to the strongest of their tier the caster has unlocked, in the May 2024 rework: a wind strike
	// at magic 13 hits for 8, not
	// 2. The ladders are the four unlock levels against the max hit they carry.
	private static final int[] STRIKE_LEVELS = {1, 5, 9, 13};
	private static final int[] STRIKE_HITS = {2, 4, 6, 8};
	private static final int[] BOLT_LEVELS = {17, 23, 29, 35};
	private static final int[] BOLT_HITS = {9, 10, 11, 12};
	private static final int[] BLAST_LEVELS = {41, 47, 53, 59};
	private static final int[] BLAST_HITS = {13, 14, 15, 16};
	private static final int[] WAVE_LEVELS = {62, 65, 70, 75};
	private static final int[] WAVE_HITS = {17, 18, 19, 20};
	private static final int[] SURGE_LEVELS = {81, 85, 90, 95};
	private static final int[] SURGE_HITS = {21, 22, 23, 24};

	/**
	 * Whether this is an elemental spell of the given element, which is what
	 * elemental weakness turns on. Only the standard spellbook's ladders count -
	 * strike, bolt, blast, wave, surge - and the name carries both halves, so no
	 * second table is needed. The ancient spells share none of these endings,
	 * which is what keeps a barrage out of it.
	 */
	boolean isElement(String element)
	{
		if (element == null)
		{
			return false;
		}
		final String name = displayName.toLowerCase(Locale.ROOT);
		return name.startsWith(element.toLowerCase(Locale.ROOT) + " ")
			&& (name.endsWith(" strike") || name.endsWith(" bolt") || name.endsWith(" blast")
			|| name.endsWith(" wave") || name.endsWith(" surge"));
	}

	/** The max hit at this magic level. Only the elemental spells move. */
	int maxHitAt(int magicLevel)
	{
		final int[] levels;
		final int[] hits;
		final String name = displayName;
		if (name.endsWith("Strike") && isElemental(name))
		{
			levels = STRIKE_LEVELS;
			hits = STRIKE_HITS;
		}
		else if (name.endsWith("Bolt") && isElemental(name))
		{
			levels = BOLT_LEVELS;
			hits = BOLT_HITS;
		}
		else if (name.endsWith("Blast") && isElemental(name))
		{
			levels = BLAST_LEVELS;
			hits = BLAST_HITS;
		}
		else if (name.endsWith("Wave") && isElemental(name))
		{
			levels = WAVE_LEVELS;
			hits = WAVE_HITS;
		}
		else if (name.endsWith("Surge") && isElemental(name))
		{
			levels = SURGE_LEVELS;
			hits = SURGE_HITS;
		}
		else
		{
			return baseMaxHit;
		}
		int best = baseMaxHit;
		for (int i = 0; i < levels.length; i++)
		{
			if (magicLevel >= levels[i])
			{
				best = Math.max(best, hits[i]);
			}
		}
		return best;
	}

	// Wind, Water, Earth and Fire only. Saradomin Strike and the god spells share the suffixes but not the mechanic.
	private static boolean isElemental(String name)
	{
		return name.startsWith("Wind ") || name.startsWith("Water ")
			|| name.startsWith("Earth ") || name.startsWith("Fire ");
	}

	private static final Map<Integer, Spell> BY_VARBIT = new HashMap<>();
	private static final Map<String, Spell> BY_DISPLAY_NAME = new HashMap<>();

	static
	{
		for (Spell spell : values())
		{
			if (spell.varbitValue >= 0)
			{
				BY_VARBIT.put(spell.varbitValue, spell);
			}
			BY_DISPLAY_NAME.put(spell.displayName.toLowerCase(Locale.ROOT), spell);
		}
	}

	/** Value of {@code VarbitID.AUTOCAST_SPELL}, or -1 when the spell can't be autocast. */
	private final int varbitValue;

	private final String displayName;

	/** Max hit before magic damage bonuses. */
	private final int baseMaxHit;

	private final Spellbook spellbook;

	/**
	 * Whether this spell reaches its target without a projectile the client
	 * shows. The ancient area spells land on the tick they are cast and give
	 * none, so their attacks are taken from the hitsplat instead.
	 */
	boolean landsWithoutProjectile()
	{
		return displayName.endsWith("Burst") || displayName.endsWith("Barrage");
	}

	/** The autocast spell for a varbit value, or null when nothing is set to autocast. */
	static Spell forVarbit(int varbitValue)
	{
		return BY_VARBIT.get(varbitValue);
	}

	/**
	 * The spell with this name, or null if it is not a combat spell. Reads a
	 * manual cast off the widget clicked, which carries a name but no id.
	 */
	static Spell forDisplayName(String name)
	{
		if (name == null)
		{
			return null;
		}
		return BY_DISPLAY_NAME.get(name.toLowerCase(Locale.ROOT));
	}
}
